function viewHits(i){let r=configDraft.intercept[i];modal('近 30 天命中记录 · '+esc(r.name),notice('累计命中 '+r.hits+' 次，以下展示最近的示例记录。')+table(['触发时间','主 / 子档案','触发场景','处理结果'],Array.from({length:Math.min(5,r.hits)},(_,j)=>['2026-10-'+(15-j)+' 10:2'+j,'CUS-'+(10086+j)+' / CUS-'+(20099+j),['录入手机号','企微加微','创建订单'][j%3],badge(j%2?'已审核':'待审核',j%2?'green':'orange')])),'',true)}
function depositPage(){return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索预约金仲裁规则" placeholder="搜索预约金仲裁规则名称" value="'+esc(depositPolicyQuery)+'" oninput="depositPolicyQuery=this.value;refreshDepositPolicyRows()"></div>'+btn('重置',"depositPolicyQuery='';render()",'text'))+contentModule('有效期配置',table(['成员状态','有效期','超期处理'],[['<strong>在职成员</strong>','<div class="input-with-unit"><input type="number" min="0" aria-label="在职成员有效期" value="'+configDraft.deposit.active+'" oninput="configDraft.deposit.active=Number(this.value)"><span>个月</span></div>','视为无保护权益'],['<strong>离职成员</strong>','<div class="input-with-unit"><input type="number" min="0" aria-label="离职成员有效期" value="'+configDraft.deposit.left+'" oninput="configDraft.deposit.left=Number(this.value)"><span>个月</span></div>','视为无保护权益']]))+contentModule('三级预约金仲裁','<div id="depositPolicyRows">'+depositPolicyRows()+'</div>')}
const ARB_FIELDS={
 'main.stage':{label:'主订单 · 所处阶段',type:'enum',values:['线上','线下']},'child.stage':{label:'子订单 · 所处阶段',type:'enum',values:['线上','线下']},
 'main.status':{label:'主订单 · 订单状态',type:'enum',values:['待排客','已排客','已到店','已超时']},'child.status':{label:'子订单 · 订单状态',type:'enum',values:['待排客','已排客','已到店','已超时']},
 'main.deposit':{label:'主订单 · 预约金金额',type:'number'},'child.deposit':{label:'子订单 · 预约金金额',type:'number'},
 'main.valid':{label:'主订单 · 预约金有效性',type:'enum',values:['有效','过期','无预约金']},'child.valid':{label:'子订单 · 预约金有效性',type:'enum',values:['有效','过期','无预约金']},
 'main.assignee':{label:'主订单 · 排客人',type:'enum',values:['有','无']},'child.assignee':{label:'子订单 · 排客人',type:'enum',values:['有','无']},
 'main.member':{label:'主订单 · 成员状态',type:'enum',values:['在职','离职']},'child.member':{label:'子订单 · 成员状态',type:'enum',values:['在职','离职']},
 'main.paidAt':{label:'主订单 · 预约金支付时间',type:'date'},'child.paidAt':{label:'子订单 · 预约金支付时间',type:'date'}
};
const ARB_OPS={eq:'等于',ne:'不等于',in:'属于任一',notin:'不属于',gt:'大于',gte:'大于等于',lt:'小于',lte:'小于等于',before:'早于',after:'晚于'};
const ARB_ACTIONS={keepMain:'保留主订单，流退子订单',keepChild:'保留子订单，流退主订单',keepBoth:'两笔订单都保留',manual:'转人工审核',intercept:'触发前置拦截，转人工审核',latest:'保留最近支付预约金的一方',earliest:'保留最先支付预约金的一方',valid:'保留预约金有效的一方',childHistory:'保留子订单，主超时订单作为历史保留',validity:'按预约金有效期仲裁',continue:'继续匹配下一条规则'};
let arbSelectedId='arb-2';
const arbLeaf=(field,operator='eq',value='')=>({field,operator,value,mode:'value'});
const arbGroup=(join,children)=>({join,children});
function arbLegacyAction(s){return ({'保留主，流退子':'keepMain','流退子，保留主':'keepMain','保留子，流退主':'keepChild','流退主，保留子':'keepChild','两笔都保留':'keepBoth','推人工审核':'manual','触发前置拦截，推人工审核':'intercept','保留最近支付方':'latest','保留先支付方':'earliest','保留有效期内方':'valid','保留子，主超时订单作为历史保留':'childHistory','进入第二步：有效期仲裁':'validity','进入下一步':'continue'})[s]||'manual'}
function migrateArbitration(old){
 if(old?.schema===2)return clone(old);
 const source=clone(old||defaults.arbitration),A=source.A||[],B=source.B||[],C=source.C||[],D=source.D||[],rules=[];
 const c=arbLeaf,g=arbGroup,online=[c('main.stage','eq','线上'),c('child.stage','eq','线上')],paid=[...online,c('main.deposit','gt',0),c('child.deposit','gt',0)],unpaid=[...online,c('main.deposit','eq',0),c('child.deposit','eq',0)];
 const add=(name,children,action,note='')=>rules.push({id:'arb-'+(rules.length+1),name,enabled:true,when:g('all',clone(children)),action,note});
 if(B[0]===D[0]&&B[0]===D[2])add('子订单已到店，先核对业务数据',[c('child.status','eq','已到店')],arbLegacyAction(B[0]),'到店订单关联签到、消耗与现场照片，优先交由人工核实。');
 else{add('主线上、子已到店',[c('main.stage','eq','线上'),c('child.status','eq','已到店')],arbLegacyAction(B[0]));add('双方均已到店',[c('main.status','eq','已到店'),c('child.status','eq','已到店')],arbLegacyAction(D[0]));add('主已超时、子已到店',[c('main.status','eq','已超时'),c('child.status','eq','已到店')],arbLegacyAction(D[2]));}
 add('线上订单，仅主订单有预约金',[...online,c('main.deposit','gt',0),c('child.deposit','eq',0)],arbLegacyAction(A[1]),'优先保留有预约金保护的主订单。');
 add('线上订单，仅子订单有预约金',[...online,c('main.deposit','eq',0),c('child.deposit','gt',0)],arbLegacyAction(A[2]));
 if(A[0]==='进入第二步：有效期仲裁'){
  add('双方预约金过期，保留最近支付方',[...paid,c('main.valid','eq','过期'),c('child.valid','eq','过期')],'latest');
  add('仅一方预约金有效，保留有效方',[...paid,g('any',[g('all',[c('main.valid','eq','有效'),c('child.valid','eq','过期')]),g('all',[c('main.valid','eq','过期'),c('child.valid','eq','有效')])])],'valid');
  add('双方预约金有效，保留先支付方',[...paid,c('main.valid','eq','有效'),c('child.valid','eq','有效')],'earliest');
 }else add('线上订单，双方都有预约金',paid,arbLegacyAction(A[0]));
 if(A[3]==='进入第三步：看排客人'){
  add('无预约金，仅主订单有排客人',[...unpaid,c('main.assignee','eq','有'),c('child.assignee','eq','无')],arbLegacyAction(A[5]));
  add('无预约金，仅子订单有排客人',[...unpaid,c('main.assignee','eq','无'),c('child.assignee','eq','有')],arbLegacyAction(A[4]));
  if(A[6]===A[7])add('无预约金，排客信息无法区分',[...unpaid,g('any',[g('all',[c('main.assignee','eq','有'),c('child.assignee','eq','有')]),g('all',[c('main.assignee','eq','无'),c('child.assignee','eq','无')])])],arbLegacyAction(A[6]),'双方都有排客人，或者双方都无排客人时，转人工判断。');
  else{add('无预约金，双方有排客人',[...unpaid,c('main.assignee','eq','有'),c('child.assignee','eq','有')],arbLegacyAction(A[6]));add('无预约金，双方无排客人',[...unpaid,c('main.assignee','eq','无'),c('child.assignee','eq','无')],arbLegacyAction(A[7]));}
 }else add('线上订单，双方均无预约金',unpaid,arbLegacyAction(A[3]));
 add('主订单在线上，子订单已超时',[c('main.stage','eq','线上'),c('child.status','eq','已超时')],arbLegacyAction(B[1]));
 add('主已到店，子线上订单有预约金',[c('main.status','eq','已到店'),c('child.stage','eq','线上'),c('child.deposit','gt',0)],arbLegacyAction(C[0]));
 add('主已到店，子线上订单无预约金',[c('main.status','eq','已到店'),c('child.stage','eq','线上'),c('child.deposit','eq',0)],arbLegacyAction(C[1]));
 add('主已超时，保留子的线上订单',[c('main.status','eq','已超时'),c('child.stage','eq','线上')],arbLegacyAction(C[2]));
 if(D[1]===D[3])add('主订单在线下，子订单已超时',[c('main.stage','eq','线下'),c('child.status','eq','已超时')],arbLegacyAction(D[1]));
 else{add('主已到店，子已超时',[c('main.status','eq','已到店'),c('child.status','eq','已超时')],arbLegacyAction(D[1]));add('双方均已超时',[c('main.status','eq','已超时'),c('child.status','eq','已超时')],arbLegacyAction(D[3]));}
 return {schema:2,match:'first',fallback:'manual',rules,previousConfiguration:source};
}
function initializeArbitration(){const legacy=clone(defaults.arbitration);state.config.arbitration=migrateArbitration(state.config.arbitration||legacy);if(state.drafts.arbitration)state.drafts.arbitration=migrateArbitration(state.drafts.arbitration);defaults.arbitration=migrateArbitration(legacy);configDraft.arbitration=clone(state.config.arbitration)}
function arbConfig(){return configDraft.arbitration}
function arbCurrent(){if(arbEditing)return arbEditing.rule;let c=arbConfig();let r=c.rules.find(x=>x.id===arbSelectedId)||c.rules[0];if(r)arbSelectedId=r.id;return r}
function arbCount(n){return n.children?n.children.reduce((s,c)=>s+arbCount(c),0):1}
function arbNode(path){let n=arbCurrent().when;if(path)path.split('.').forEach(i=>n=n.children[+i]);return n}
function arbRefresh(){render()}
function arbChoose(id){let r=arbConfig().rules.find(x=>x.id===id);if(!r)return;arbSelectedId=id;arbEditing={originalId:id,isNew:false,rule:clone(r)};render();$('#arbRuleName')?.focus()}
function arbitrationPage(){return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索仲裁规则" placeholder="搜索仲裁规则名称" value="'+esc(arbListQuery)+'" oninput="arbListQuery=this.value;refreshArbList()"></div>'+btn('重置',"arbListQuery='';render()",'text'))+contentModule('仲裁规则','<div class="arbitration-fallback">'+field('未命中规则时',select([['manual','转人工审核'],['keepMain','保留主订单，流退子订单'],['keepChild','保留子订单，流退主订单'],['keepBoth','两笔订单都保留']],arbConfig().fallback,'aria-label="订单仲裁未命中规则处理动作" onchange="arbConfig().fallback=this.value"'))+'</div><div id="arbListRows">'+arbTableRows()+'</div>','<button id="arbAddButton" class="btn primary" onclick="arbAddRule()">'+icon('plus')+'新增仲裁规则</button>')}
function arbActionHint(action){return ({keepMain:'子订单按所处阶段标记合并流退，支付流水保留，不自动退款。',keepChild:'主订单按所处阶段标记合并流退，客户主档案关系保持独立判断。',keepBoth:'两笔订单同时保留；已超时订单作为历史保留。',manual:'停止自动仲裁，生成待审核工单。',intercept:'记录拦截原因并推送人工审核，不自动处理订单。',latest:'比较两笔预约金的支付时间，保留较晚的一方；时间相同转人工审核。',earliest:'比较两笔预约金的支付时间，保留较早的一方；时间相同转人工审核。',valid:'按在职 / 离职有效期，保留唯一有效的一方；无法区分则转人工审核。',childHistory:'保留子的线上订单，主订单须为已超时状态并作为历史保留。',validity:'按预约金有效期页面配置的条件、顺序和处理动作执行。',continue:'命中后继续检查下一条规则，不在此处执行订单处理。'})[action]||''}
function arbOperators(f,mode='value'){let type=ARB_FIELDS[f]?.type;return type==='number'?['eq','ne','gt','gte','lt','lte']:type==='date'?['eq','ne','before','after']:mode==='field'?['eq','ne']:['eq','ne','in','notin']}
function arbDefaultValue(field){let f=ARB_FIELDS[field];return f.type==='number'?0:f.type==='date'?'2026-10-15':f.values[0]}
function arbCompatibleFields(field){let f=ARB_FIELDS[field];return Object.entries(ARB_FIELDS).filter(([k,v])=>k!==field&&v.type===f.type&&(f.type!=='enum'||JSON.stringify(v.values)===JSON.stringify(f.values))).map(([k,v])=>[k,v.label])}
function arbRenderGroup(g,path,depth){let pathq="'"+path+"'",root=path==='';return '<div class="arb-group '+(g.join==='any'?'is-any':'')+'" data-group-path="'+path+'"><div class="arb-group-head"><div class="row"><span class="arb-join-word">'+(g.join==='all'?'且':'或')+'</span>'+select([['all','全部条件满足（AND）'],['any','任一条件满足（OR）']],g.join,'aria-label="'+(root?'根条件组':'子条件组')+'匹配方式" onchange="arbNode('+esc(pathq)+').join=this.value;arbRefresh()"')+'</div><div class="actions">'+btn('添加条件','arbAddNode('+pathq+',false)','text','plus')+(depth<2?btn('添加条件组','arbAddNode('+pathq+',true)','text','layers'):'')+(!root?'<button class="icon-btn" aria-label="删除条件组" onclick="arbRemoveNode('+esc(pathq)+')">'+icon('close')+'</button>':'')+'</div></div><div class="arb-group-body">'+(g.children.length?g.children.map((n,i)=>{let p=path?path+'.'+i:String(i);return (i?'<div class="arb-connector">'+(g.join==='all'?'且':'或')+'</div>':'')+(n.children?arbRenderGroup(n,p,depth+1):arbRenderCondition(n,p))}).join(''):'<div class="arb-empty">'+icon('plus')+'添加主订单、子订单的判断条件，或创建嵌套条件组。</div>')+'</div></div>'}
function arbRenderCondition(c,path){let f=ARB_FIELDS[c.field],q="'"+path+"'",attrs='onchange="arbEdit('+esc(q)+',\'value\',this.value)"',value;if(c.mode==='field')value=select(arbCompatibleFields(c.field),c.value,'aria-label="对比字段" '+attrs);else if(['in','notin'].includes(c.operator))value='<div class="arb-value-chips">'+f.values.map(v=>'<label class="'+(Array.isArray(c.value)&&c.value.includes(v)?'on':'')+'"><input type="checkbox" '+(Array.isArray(c.value)&&c.value.includes(v)?'checked':'')+' onchange="arbToggleValue('+esc(q)+',\''+v+'\',this.checked)">'+v+'</label>').join('')+'</div>';else value=f.type==='enum'?select(f.values,c.value,'aria-label="条件取值" '+attrs):'<input type="'+(f.type==='date'?'date':'number')+'" '+(f.type==='number'?'min="0" step="0.01"':'')+' aria-label="条件取值" value="'+esc(c.value)+'" '+attrs+'>';return '<div class="arb-condition" data-condition-path="'+path+'"><div class="arb-condition-main">'+select(Object.entries(ARB_FIELDS).map(([k,v])=>[k,v.label]),c.field,'aria-label="条件字段" onchange="arbEdit('+esc(q)+',\'field\',this.value)"')+select(arbOperators(c.field,c.mode).map(o=>[o,ARB_OPS[o]]),c.operator,'aria-label="比较方式" onchange="arbEdit('+esc(q)+',\'operator\',this.value)"')+'<button class="icon-btn" aria-label="删除条件" onclick="arbRemoveNode('+esc(q)+')">'+icon('close')+'</button></div><div class="arb-condition-value">'+select([['value','指定值'],['field','对比另一字段']],c.mode,'aria-label="取值方式" onchange="arbEdit('+esc(q)+',\'mode\',this.value)"')+value+'</div></div>'}
function arbEdit(path,key,value){let c=arbNode(path);if(key==='field'){c.field=value;c.mode='value';c.operator='eq';c.value=arbDefaultValue(value)}else if(key==='mode'){c.mode=value;c.operator='eq';c.value=value==='field'?arbCompatibleFields(c.field)[0][0]:arbDefaultValue(c.field)}else if(key==='operator'){c.operator=value;c.value=['in','notin'].includes(value)?(Array.isArray(c.value)?c.value:[c.value]):(Array.isArray(c.value)?c.value[0]??arbDefaultValue(c.field):c.value)}else c.value=c.mode==='value'&&ARB_FIELDS[c.field].type==='number'?(value===''?'':Number(value)):value;arbRefresh()}
function arbToggleValue(path,value,checked){let c=arbNode(path);c.value=checked?[...new Set([...c.value,value])]:c.value.filter(x=>x!==value);arbRefresh()}
function arbAddNode(path,group){arbNode(path).children.push(group?arbGroup('any',[arbLeaf('child.status','eq','已到店')]):arbLeaf('main.status','eq','待排客'));arbRefresh()}
function arbRemoveNode(path){let p=path.split('.'),index=+p.pop();arbNode(p.join('.')).children.splice(index,1);arbRefresh()}
function arbAddRule(){let id='custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);arbEditing={originalId:null,isNew:true,rule:{id,name:'',enabled:true,when:arbGroup('all',[arbLeaf('main.status','eq','待排客')]),action:'manual',note:''}};render();$('#arbRuleName')?.focus()}
function arbDuplicate(id){let original=arbConfig().rules.find(r=>r.id===id)||arbCurrent(),r=clone(original);r.id='copy-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);r.name+='（副本）';r.enabled=false;arbEditing={originalId:null,isNew:true,rule:r};render();$('#arbRuleName')?.focus()}
function arbDeleteRule(id){let r=arbConfig().rules.find(r=>r.id===id)||arbCurrent();modal('删除仲裁规则','<p>确认删除“'+esc(r.name)+'”？</p>',btn('取消','closeModal()')+btn('删除',"arbCommitDelete('"+r.id+"')",'danger'))}
function arbDescribe(n){if(n.children){if(!n.children.length)return '<span class="negative">未配置条件</span>';return '（'+n.children.map(arbDescribe).join(n.join==='all'?' <span class="arb-logic-inline">且</span> ':' <span class="arb-logic-inline any">或</span> ')+'）'}return '<span>'+esc(ARB_FIELDS[n.field]?.label||'未知字段')+' '+esc(ARB_OPS[n.operator])+' <b>'+esc(n.mode==='field'?ARB_FIELDS[n.value]?.label||'未选择':Array.isArray(n.value)?n.value.join(' / '):n.value)+'</b></span>'}
function validateArbitration(cfg){let errors=[];cfg.rules.forEach((r,i)=>{const prefix='规则 '+(i+1)+'：';if(!r.name.trim())errors.push(prefix+'请填写名称');if(!ARB_ACTIONS[r.action])errors.push(prefix+'请选择处理动作');function walk(n,depth){if(n.children){if(!n.children.length)errors.push(prefix+'条件组不能为空');if(!['all','any'].includes(n.join))errors.push(prefix+'请选择条件组匹配方式');if(depth>2)errors.push(prefix+'条件组最多嵌套三层');n.children.forEach(x=>walk(x,depth+1));return}let f=ARB_FIELDS[n.field];if(!f){errors.push(prefix+'字段无效');return}if(!arbOperators(n.field,n.mode).includes(n.operator))errors.push(prefix+'比较方式不适用于该字段');if(n.mode==='field'){if(!arbCompatibleFields(n.field).some(([k])=>k===n.value))errors.push(prefix+'请选择兼容的对比字段')}else if(f.type==='number'){if(n.value===''||!Number.isFinite(Number(n.value))||Number(n.value)<0)errors.push(prefix+'金额必须为不小于0的数字')}else if(f.type==='date'){if(!n.value||!Number.isFinite(Date.parse(n.value)))errors.push(prefix+'请填写有效日期')}else if(['in','notin'].includes(n.operator)){if(!Array.isArray(n.value)||!n.value.length||n.value.some(v=>!f.values.includes(v)))errors.push(prefix+'请至少选择一个有效取值')}else if(!f.values.includes(n.value))errors.push(prefix+'请填写有效条件值')}
 walk(r.when,0)});return [...new Set(errors)]}
function arbDerived(data){let out={};for(let side of ['main','child']){let o=data[side],ref=Date.parse(data.reference+'T12:00:00'),paid=Date.parse(o.paidAt+'T12:00:00'),expiry=new Date(paid);let months=Number(o.member==='离职'?configDraft.deposit.left:configDraft.deposit.active);let day=expiry.getDate();expiry.setDate(1);expiry.setMonth(expiry.getMonth()+months);let last=new Date(expiry.getFullYear(),expiry.getMonth()+1,0).getDate();expiry.setDate(Math.min(day,last));Object.entries(o).forEach(([k,v])=>out[side+'.'+k]=v);out[side+'.deposit']=Number(o.deposit);out[side+'.stage']=['待排客','已排客'].includes(o.status)?'线上':'线下';out[side+'.valid']=Number(o.deposit)<=0?'无预约金':ref<=expiry.getTime()?'有效':'过期'}return out}
function arbMatches(n,data){if(n.children)return n.children.length>0&&(n.join==='all'?n.children.every(x=>arbMatches(x,data)):n.children.some(x=>arbMatches(x,data)));let a=data[n.field],b=n.mode==='field'?data[n.value]:n.value;if(ARB_FIELDS[n.field].type==='number'){a=Number(a);if(!Array.isArray(b))b=Number(b)}if(ARB_FIELDS[n.field].type==='date'){a=Date.parse(a);b=Date.parse(b);if(!Number.isFinite(a)||!Number.isFinite(b))return false}return ({eq:()=>a===b,ne:()=>a!==b,in:()=>Array.isArray(b)&&b.includes(a),notin:()=>Array.isArray(b)&&!b.includes(a),gt:()=>a>b,gte:()=>a>=b,lt:()=>a<b,lte:()=>a<=b,before:()=>a<b,after:()=>a>b}[n.operator]||(()=>false))()}
function arbResolve(action,data){let main=Number(data['main.deposit'])>0,child=Number(data['child.deposit'])>0,validMain=data['main.valid']==='有效',validChild=data['child.valid']==='有效',a=Date.parse(data['main.paidAt']),b=Date.parse(data['child.paidAt']);if(action==='validity'){if(!main||!child)return {action:'manual',reason:'预约金数据不完整，交由人工核实'};return resolveDepositPolicy(data)}if(action==='valid'){if(!main||!child||validMain===validChild)return {action:'manual',reason:'无法区分唯一有效方，转人工审核'};return {action:validMain?'keepMain':'keepChild',reason:'仅'+(validMain?'主':'子')+'订单预约金在有效期内'}}if(action==='latest'||action==='earliest'){if(!main||!child||!Number.isFinite(a)||!Number.isFinite(b)||a===b)return {action:'manual',reason:'支付时间相同或预约金数据不足，转人工审核'};let keep=action==='latest'?a>b:a<b;return {action:keep?'keepMain':'keepChild',reason:'比较支付时间，保留'+(action==='latest'?'较晚':'较早')+'支付的一方'}}if(action==='childHistory'&&data['main.status']!=='已超时')return {action:'manual',reason:'主订单并非已超时，需人工核实后处理'};return {action,reason:arbActionHint(action)}}
function evaluateArbitration(cfg,data){let trace=[],chosen=null;for(let i=0;i<cfg.rules.length;i++){let r=cfg.rules[i],hit=r.enabled&&arbMatches(r.when,data),result=!chosen&&hit?arbResolve(r.action,data):null,status=!r.enabled?'已停用':chosen?'未执行':hit?result.action==='continue'?'命中 · 继续':'命中执行':'不满足';trace.push({id:r.id,name:r.name,status,hit,index:i+1});if(result&&result.action!=='continue')chosen={rule:r,index:i+1,...result}}let fallback=arbResolve(['manual','keepMain','keepChild','keepBoth'].includes(cfg.fallback)?cfg.fallback:'manual',data);return {chosen,trace,action:chosen?.action||fallback.action,reason:chosen?.reason||'所有启用规则均未命中执行动作，'+fallback.reason}}
