function flowFooter(){let c=current();return footer('已提交方案锁定，执行与结果可追溯。',btn('关闭','cxCloseWorkbench()')+(c.resultData&&c.status!=='已完成'?btn('确认结果并完成','confirmAdjustment()','primary'):c.execution?.status==='执行失败'?btn('重试执行','clRetry()','primary'):''))}
function ticketPage(withFooter=true){let c=current(),n=flowStage(c),banner=c.paused?'<div class="cw-warning"><h3>有一项结果需要核查</h3><p>'+esc(c.pauseReason||'请核实数据后记录结论，再恢复处理。')+'</p>'+btn('记录结论并继续','resumeTicket()','text')+'</div>':c.status==='待补充申请'?'<div class="cw-warning"><h3>申请需要补充信息</h3><p>'+esc(c.returnReason||'请补充问题说明和归属证据。')+'</p></div>':c.status==='待补充信息'?'<div class="cw-warning"><h3>还有数据归属未明确</h3><p>当前选择会保留，未确定的项目可按示例方案继续演示。</p></div>':'';return flowWorkHeader(c)+banner+'<div class="cw-layout"><div>'+(c.status==='已完成'?flowResult(true):n===1?flowReview():n===2?flowPlan():n===3?flowExecution():flowResult(false))+'</div><aside class="cw-aside" id="flowAside">'+flowAside(c)+'</aside></div>'+(withFooter?'<div id="flowFooter">'+flowFooter()+'</div>':'')}
function approvalPage(){return ticketPage()}
function snapshotPage(){return ticketPage()}
function processPage(){return ticketPage()}
function identityPage(){return ticketPage()}
function recalcPage(){return ticketPage()}
function adjustmentPage(){return ticketPage()}
function flowReturnApplication(){if(flowStage()!==1)return;modal('退回补充申请',field('需要补充什么','<textarea id="returnNote" placeholder="说明缺少的证据或需要进一步核实的问题"></textarea>',false),btn('取消','closeModal()')+btn('退回补充',"flowCommitReturn()",'primary'))}
