function flowPlan(){let c=current(),count=flowCounts(c);return '<section class="panel"><div class="cw-section-intro"><div class="spread"><div><div class="cw-step-index">02 / 制定方案</div><h2>先明确归属，再统一纠正</h2></div><span class="cw-save">'+icon('check')+' 自动保存</span></div><p>从需要人工判断的数据开始，逐项确认处理方式。</p></div><div class="tabs cw-plan-tabs" role="tablist">'+[['manual','待判断归属',count.manual,c.manual.length],['transfer','业务记录',count.transfer,c.directRows?.length||c.transfer.length],['finance','资金纠正',count.finance,c.finance.length],['identity','身份信息',c.planIdentityReviewed?1:0,1]].map(([k,t,v,total])=>'<button data-flow-tab="'+k+'" role="tab" aria-selected="'+(flowTab===k)+'" class="tab '+(flowTab===k?'active':'')+'" tabindex="'+(flowTab===k?'0':'-1')+'" onkeydown="cxPlanTabKey(event)" onclick="flowTab=\''+k+'\';render()">'+t+'</button>').join('')+'</div><div role="tabpanel">'+(flowTab==='manual'?manualTab():flowTab==='transfer'?transferTab():flowTab==='finance'?financeTab():flowIdentity())+'</div></section>'}
function setTransfer(i,to){if(!flowCanEdit())return;let c=current(),t=c.transfer[i];if(t.executed||[5,6].includes(i))return;if(i===3&&to==='split')return splitCalls();t.to=to;t.reviewed=!!to;if(i===1)[5,6].forEach(j=>{if(!c.transfer[j].executed){c.transfer[j].to=to;c.transfer[j].reviewed=!!to}});persist();render()}
function splitCalls(){if(!flowCanEdit()||current().transfer[3].executed)return;modal('逐条确认通话归属',table(['通话时间','通话归属'],['2026-02-28','2026-03-05','2026-03-10'].map((d,i)=>[d,select([['new',current().subname+' · 独立档案'],['main',current().name+' · 主档案']],current().transfer[3].calls?.[i]||'new','id="call'+i+'"')])) ,btn('取消','closeModal();render()')+btn('保存分配','commitSplit()','primary'))}
function commitSplit(){if(!flowCanEdit()||current().transfer[3].executed)return;let t=current().transfer[3];t.calls=[0,1,2].map(i=>$('#call'+i).value);t.to='split';t.reviewed=true;persist();closeModal();render()}
function flowFinanceReason(i,v){if(!flowCanEdit()||current().finance[i].generated)return;current().finance[i].reason=v;current().finance[i].confirmed=false;flowSave();let el=$('[onchange="flowConfirmMoney('+i+',this.checked)"]');if(el)el.checked=false}
function flowConfirmMoney(i,checked){if(!flowCanEdit())return;let f=current().finance[i];if(f.generated)return;f.confirmed=checked;persist();render()}
function flowIdentityReason(v){if(!flowCanEdit()||current().identityDone)return;current().identityReason=v;current().planIdentityReviewed=false;flowSave();$('#flowIdentityConfirm').checked=false}
function flowConfirmIdentity(v){if(!flowCanEdit())return;current().planIdentityReviewed=v;persist();render()}
function flowPreview(){if(cxApplicationOpen&&clStep===3)clNext()}
function flowEditPlan(){if(cxApplicationOpen){clStep=2;render()}}
function flowConfirmExecute(){if(current().workflowVersion===4&&current().approvedPlan)clRetry();else toast('请先提交完整纠错方案')}
function flowCanClose(c=current()){return c.step===8&&!c.paused}
function flowResultCheck(i,v){let c=current();if(c.step!==8||c.paused)return;c.resultChecks[i]=v;flowSave()}
function financialActions(){let c=current(),done=c.status==='已完成';return (done?kv({'确认人':esc(c.completedBy||'张三'),'完成时间':c.completedAt||c.logs.find(x=>x.step===9)?.at||c.date,'资金确认':badge('已确认','green')})+'<hr class="light-divider">':'')+['财务差异与原始流水一致，冲销 / 补录金额已核对','客户数据归属、统计结果及客户类型已核对','双方身份信息正确，客户可正常访问自己的档案'].map((t,i)=>'<label class="cw-check"><input type="checkbox" '+(done||c.resultChecks?.[i]?'checked':'')+' '+(done||c.paused?'disabled':'')+' onchange="flowResultCheck('+i+',this.checked)"><span>'+t+'</span></label>').join('')+(c.cross?'<hr class="light-divider"><h3>跨门店确认记录</h3><p class="cw-inline-note">可记录两个门店的业务确认情况，也可直接完成本次演示。</p>'+[c.correctionData?.main.store||c.store,c.correctionData?.child.store||'B02 · 徐汇店'].map((s,i)=>'<div class="spread" style="padding:12px 0"><div class="small">'+s+(c.storeConfirm[i]?'<div class="tiny muted">'+esc(c.storeRecords?.[i]?.person||'已确认')+' · '+esc(c.storeRecords?.[i]?.note||'业务影响已核实')+'</div>':'')+'</div>'+(c.storeConfirm[i]?badge('已确认','green'):btn('记录确认','confirmStore('+i+')','small'))+'</div>').join(''):'')+(!done?field('处理结论（选填）','<textarea id="financeOpinion" placeholder="补充本次纠错的处理说明" oninput="current().financeOpinion=this.value;persist()">'+esc(c.financeOpinion||'')+'</textarea>'):'')}
function confirmAdjustment(){let c=current();if(!flowCanClose(c))return;modal('确认结果并完成工单',notice('财务调整将标记为已确认，原合并记录标记为已纠错，全部记录可追溯。','good','check'),btn('继续核对','closeModal()')+btn('完成工单','commitAdjustment()','primary'))}
function commitAdjustment(){let c=current();if(c.businessVersion===5){bpFinish();return}if(!flowCanClose(c))return;c.resultChecks=[true,true,true];if(c.cross){c.storeRecords||={};c.storeConfirm.forEach((confirmed,i)=>{if(!confirmed){c.storeConfirm[i]=true;c.storeRecords[i]={person:'示例联系人',note:'原型演示自动完成',at:now(),recordedBy:'张三'}}})}c.financeApproved=true;c.status='已完成';c.step=9;c.corrected=true;c.completedAt=now();c.completedBy='张三';let mergeRecord=state.mergeRecords?.find(r=>r.id===c.merge);let correctedSource=state.mergeSources?.find(s=>s.merge===c.merge&&s.sub===c.sub);if(correctedSource){correctedSource.corrected=true;correctedSource.correctionCaseId=c.id}if(mergeRecord)mrEvent(mergeRecord,'纠错工单 '+c.id+' 已完成，原档案 '+c.sub+' 的数据归属已纠正');log('确认财务、数据与身份结果，完成纠错'+(c.financeOpinion?'：'+c.financeOpinion:''),'待确认结果','已完成');closeModal();go('ticket',c.id);cxSyncLive(c);toast('工单已完成，本次原档案的纠错结果已保存')}
function confirmStore(i){if(current().step!==8||current().paused)return;modal('记录'+['静安店','徐汇店'][i]+'确认',field('确认人（选填）','<input id="storePerson" placeholder="填写已确认的业务联系人">',false)+'<br>'+field('确认依据','<textarea id="storeNote" placeholder="说明核对的订单、金额与门店影响"></textarea>',false),btn('取消','closeModal()')+btn('保存确认记录','flowStoreCommit('+i+')','primary'))}
function flowStoreCommit(i){let c=current(),p=$('#storePerson').value.trim()||'示例联系人',n=$('#storeNote').value.trim()||'原型演示确认';if(c.step!==8||c.paused)return;c.storeConfirm[i]=true;c.storeRecords||={};c.storeRecords[i]={person:p,note:n,at:now(),recordedBy:'张三'};log('记录'+['静安店','徐汇店'][i]+'确认：'+p+'；'+n);closeModal();render()}
function pauseTicket(){if(current().step!==8)return;modal('记录需要核查的问题',notice('工单会停留在当前阶段。已执行记录保留，核查完成后可继续确认。')+field('核查问题','<textarea id="pauseReason" placeholder="描述结果中的疑问与需要核实的内容"></textarea>',false),btn('取消','closeModal()')+btn('保存并暂停','flowPauseCommit()','primary'))}
function flowPauseCommit(){let c=current(),v=$('#pauseReason').value.trim()||'示例：待核查业务记录';if(c.step!==8)return;c.paused=true;c.pauseReason=v;c.status='已暂停';c.resultChecks=[false,false,false];log('暂停确认，需核查：'+v);closeModal();render()}
function resumeTicket(){if(!current().paused)return;modal('记录核查结论',notice('确认问题已核实后恢复处理。已执行数据与财务记录保持可追溯。')+field('核查结论','<textarea id="resumeReason" placeholder="填写核实经过和最终结论"></textarea>',false),btn('取消','closeModal()')+btn('恢复处理','flowResumeCommit()','primary'))}
function flowResumeCommit(){let v=$('#resumeReason').value.trim()||'示例：核查完成';let c=current();if(!c.paused)return;c.paused=false;c.status=c.step>=8?'待财务确认':'处理中';log('核查完成，恢复处理：'+v);closeModal();render()}
function flowLogs(){modal('操作记录 · '+current().id,flowLogContent(),'',true)}
