function evidenceModal(){let c=current();modal('证据材料 · '+c.evidence.length+' 份',notice('示例附件可查看核查摘要；本次上传的文件可在当前页面会话中预览。刷新后仅保留文件名。')+c.evidence.map(f=>'<div class="file-row">'+icon('file')+'<span class="flex1">'+esc(f)+'</span>'+btn('查看',"previewFile('"+encodeURIComponent(f)+"')",'text')+'</div>').join(''))}
function previewFile(encoded){let n=decodeURIComponent(encoded),f=fileObjects.get(n);if(f){let url=URL.createObjectURL(f);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}else modal('材料摘要 · '+esc(n),notice('示例材料或当前会话未加载的附件。此处不包含真实附件内容。')+body('<p class="small">示例核查：客户反馈存在非本人消费记录。原子档案手机号、到店门店与接待记录与主档案不同，需要核实双方真实归属。</p>'))}
