function approvalButtons(mobile=false){let c=current();if(flowStage(c)!==1||c.status==='待补充申请')return btn('进入当前工单',"flowOpen('"+c.id+"')",'primary');return field('核实意见','<textarea id="approvalOpinion" placeholder="核实依据（选填）" oninput="current().reviewNote=this.value;persist()">'+esc(c.reviewNote||'')+'</textarea>',false)+'<div class="actions" style="margin-top:15px">'+btn('核实通过',"approve('pass',true)",'primary')+btn('退回补充','flowReturnApplication()')+'</div>'}
