function applicationForm(mobile=false){return '<div class="form-stack">'+field('纠错原因',select([['','请选择纠错原因'],'合并了不同人','主子判定错误','订单仲裁错误','数据迁移错误','其他'],newForm.reason,'aria-label="纠错原因" onchange="newForm.reason=this.value;flowDraftSave()"'),true)+field('问题说明','<textarea id="newDescription" placeholder="发现了什么问题？已核实哪些信息？哪些数据需要纠正？" oninput="newForm.description=this.value;flowDraftSave()">'+esc(newForm.description)+'</textarea>',true)+field('核查证据（选填）',uploadForm(),false)+field('期望处理方式（选填）','<textarea placeholder="例如：将李四的订单与手机号分离到独立档案" oninput="newForm.expect=this.value;flowDraftSave()">'+esc(newForm.expect)+'</textarea>')+'</div>'}
function addFiles(files){Array.from(files).forEach(f=>{if(!newForm.evidence.includes(f.name)){newForm.evidence.push(f.name);fileObjects.set(f.name,f)}});flowDraftSave();render()}
