function cxLegacySubmitApplication(mobile=false){submitApplication(mobile)}
function completion(c=current()){return !!c.resultData&&c.directRows.every(x=>x.executed||x.to==='main')&&c.finance.every(x=>!cxAmount(x)||x.generated)&&!c.pendingItems?.length}
function progressSummary(c=current()){return '方案尚有 '+flowCounts(c).remaining+' 项待确认'}
function customerCompare(title,main){let c=current();return panel(title,body(kv({'客户':esc(main?c.name:c.subname),'编号':main?c.cus:c.sub,'手机号':main?'138****1234':'139****5678'})))}
let rvPage=1,activeReversal=null;
function allReversals(){return state.cases.flatMap(c=>c.finance.filter(f=>f.generated&&f.amount!==0).map((f,i)=>{let triple=c.financialTriples?.find(x=>x.kind==='反向冲销'&&(x.id===f.id+'-R'||x.originalId===f.originalId)),generatedAt=f.generatedAt||triple?.at||c.executedAt||c.logs?.find(x=>x.step===8)?.at||'',businessDate=f.originalAt||triple?.businessAt||'';return {id:'RV-'+c.id.slice(3)+'-'+String(i+1).padStart(2,'0'),c,f,generatedAt,businessDate,date:generatedAt.slice(0,10),effective:c.financeApproved||c.status==='已完成'}}))}
function matchingReversals(){return allReversals().filter(r=>(rvScope==='all'||(rvScope==='effective'?r.effective:!r.effective))&&(!rvFilter.q||r.c.id.includes(uiQuery(rvFilter.q))||r.id.includes(uiQuery(rvFilter.q)))&&(!rvFilter.customer||[r.c.cus,r.c.newId,r.c.name,r.c.subname,r.c.profileDraft?.name,r.c.businessPlan?.targetSnapshot?.name].join(' ').includes(uiQuery(rvFilter.customer)))&&(!rvFilter.type||r.f.type===rvFilter.type)&&(!rvFilter.from||r.date>=rvFilter.from)&&(!rvFilter.to||r.date<=rvFilter.to)&&(!rvFilter.min||Math.abs(r.f.amount)>=Number(rvFilter.min))&&(!rvFilter.max||Math.abs(r.f.amount)<=Number(rvFilter.max)))}
function reversalPage(){let rows=matchingReversals(),pages=Math.max(1,Math.ceil(rows.length/8));rvPage=Math.min(rvPage,pages);let all=allReversals(),tabs=[['all','全部记录'],['pending','待确认'],['effective','已生效']].map(([k,t])=>[k,t,"rvScope='"+k+"';rvPage=1;render()",all.filter(r=>k==='all'||(k==='effective'?r.effective:!r.effective)).length]);return pageTabs(tabs,rvScope,'冲销记录状态')+queryModule('<input aria-label="纠错工单编号" placeholder="纠错工单编号" value="'+esc(rvFilter.q)+'" oninput="rvFilter.q=this.value;rvPage=1;refreshReversalRows()"><input aria-label="客户编号或姓名" placeholder="客户编号 / 姓名" value="'+esc(rvFilter.customer)+'" oninput="rvFilter.customer=this.value;rvPage=1;refreshReversalRows()">'+select([['','全部冲销类型'],'预约金收取','预约金退还','订单支付','白条充值','白条消耗','消耗项目','已发放提成','新增订单支付','优惠券抵扣'],rvFilter.type,'aria-label="冲销类型" onchange="rvFilter.type=this.value;rvPage=1;render()"')+'<span class="small muted">冲销生成日期</span><input type="date" aria-label="冲销生成开始日期" title="按冲销生成日期筛选" value="'+rvFilter.from+'" onchange="rvFilter.from=this.value;render()"><input type="date" aria-label="冲销生成结束日期" title="按冲销生成日期筛选" value="'+rvFilter.to+'" onchange="rvFilter.to=this.value;render()"><input type="number" min="0" style="width:95px" aria-label="最小金额" placeholder="最低金额" value="'+rvFilter.min+'" onchange="rvFilter.min=this.value;render()"><input type="number" min="0" style="width:95px" aria-label="最大金额" placeholder="最高金额" value="'+rvFilter.max+'" onchange="rvFilter.max=this.value;render()">'+btn('重置',"rvFilter={q:'',customer:'',type:'',from:'',to:'',min:'',max:''};render()",'text'))+contentModule('冲销记录','<div id="reversalRows">'+reversalRowsContent(rows,pages)+'</div>',btn('导出含冲销明细',"exportReversals(false)",'','download')+btn('导出只看净值',"exportReversals(true)",'','download'))}
function reversalRowsContent(rows,pages){return table(['冲销编号 / 关联工单','类型 / 生成时间','原始金额','冲销金额','补录金额','状态','操作'],rows.slice((rvPage-1)*8,rvPage*8).map(r=>['<span class="mono">'+r.id+'</span><div style="margin-top:4px">'+ticketLink(r.c)+'</div>',esc(r.f.type)+'<div>'+badge('纠错','purple')+'</div><div class="tiny muted">'+esc(r.generatedAt||'生成时间未保存')+'</div>',cxSign(cxSigned(r.f,true))+'<div class="muted mono">'+esc(r.c.cus)+'</div>','<span class="'+(-cxSigned(r.f)<0?'negative':'positive')+'">'+cxSign(-cxSigned(r.f))+'</span><div class="muted mono">'+esc(r.c.cus)+'</div>','<span class="'+(cxSigned(r.f)<0?'negative':'positive')+'">'+cxSign(cxSigned(r.f))+'</span><div class="muted mono">'+esc(r.c.newId)+'</div>',badge(r.effective?'已生效':'待确认',r.effective?'green':'orange'),btn('详情',"openReversal('"+r.id+"')",'text')]))+(!rows.length?empty('暂无符合条件的冲销记录'):'')+'<div class="pagination"><span>共 '+rows.length+' 组 · 第 '+rvPage+' / '+pages+' 页</span><div>'+btn('上一页','rvPage=Math.max(1,rvPage-1);render()','small')+btn('下一页','rvPage=Math.min('+pages+',rvPage+1);render()','small')+'</div></div>'}
