function mrCorrectionSummary(c){if(c.businessVersion===5)return '已完成'+({split:'客户分离与业务归属',partial:'选定业务',performance:'员工业绩',profile:'基本资料'}[c.businessPlan.scope]||'本次')+'纠正，客户与员工调整明细可追溯。';if(c.pendingItems?.length)return '已执行本次明确的数据归属；仍有 '+c.pendingItems.length+' 条待定记录保留主档案，可继续补充归属。';let r=state.mergeRecords?.find(r=>r.id===c.merge);return r?.pair.length>2&&mrStatus(r)==='部分已纠错'?'本次原档案已完成纠错；该次合并还有其他原档案，可继续按需核对。':'主档案与独立档案已归位，本次纠错已完成。'}
function mrCorrection(r){return state.cases.find(c=>c.merge===r.id&&c.status!=='已完成')||state.cases.find(c=>c.merge===r.id&&c.status==='已完成')}
function mrStatus(r){if(r.revoked)return '已撤销';let cases=state.cases.filter(c=>c.merge===r.id),active=cases.find(c=>!['已完成','已终止'].includes(c.status));if(active)return '纠错中';if(cases.some(c=>c.pendingItems?.length))return '部分已纠错';if(cases.some(c=>c.businessPlan?.targetDefinitionVersion))return '部分已纠错';if(cases.length){let children=r.pair.filter(c=>c.id!==r.plan.mainId);return children.every(child=>cases.some(c=>c.sub===child.id&&c.status==='已完成'&&(c.businessVersion!==5||c.businessPlan.scope==='split')))?'已纠错':'部分已纠错'}if(r.archived||mrTime(r.retainUntil)<Date.now())return '快照已归档';if(mrTime(r.coolingUntil)>Date.now())return '冷静期中';return '已合并'}
function mrBadge(s){return badge(s,['已合并','已执行','已通过','已纠错'].includes(s)?'green':['待审核','冷静期中','纠错中','部分已纠错','执行失败'].includes(s)?'orange':['已驳回','已撤销'].includes(s)?'red':'')}
function mrSetView(v){go(v==='records'?'merge-records':'merge-candidates')}
function mrSearch(){if(mrFilter.from&&mrFilter.to&&mrFilter.from>mrFilter.to){toast('开始日期不能晚于结束日期');return}mrApplied=clone(mrFilter);mrPage=1;mrSelected.clear();render()}
function mrReset(){mrFilter={q:'',store:'',status:'',source:'',scene:'',reason:'',from:'',to:''};mrSearch()}
function mrRows(){let f=mrApplied;return state.mergeRecords.filter(r=>{let s=mrStatus(r);return (!f.q||[r.id,r.applicationId,r.match,...r.pair.flatMap(c=>[c.name,c.id,c.phone,c.oldPhone])].join(' ').toLowerCase().includes(uiQuery(f.q).toLowerCase()))&&(!f.store||r.pair.some(c=>c.store===f.store))&&(!f.status||s===f.status)&&(!f.source||r.method===f.source)&&(!f.scene||r.trigger===f.scene)&&(!f.from||r.time.slice(0,10)>=f.from)&&(!f.to||r.time.slice(0,10)<=f.to)}).sort((a,b)=>b.time.localeCompare(a.time))}
function mergeRecordsPage(){mrView='records';return mgPage(true)}
function mrListTable(){let all=mrRows(),pages=Math.max(1,Math.ceil(all.length/7));mrPage=Math.max(1,Math.min(mrPage,pages));let rows=all.slice((mrPage-1)*7,mrPage*7);return table(['合并编号 / 时间','主档案','被合并档案','合并方式 / 场景','门店','状态','操作'],rows.map(r=>{let data=mhData(r),p={after:data.after||data.before.find(c=>c.id===r.plan.mainId)||data.before[0],children:data.before.filter(c=>c.id!==r.plan.mainId)};let status=mrStatus(r),c=mrCorrection(r);return [`<button class="inline-link mono" onclick="mrOpen('record',${esc(mrQuote(r.id))})">${r.id}</button><div class="tiny muted">${r.time.slice(0,16)}</div>`,mrCustomerBrief(p.after),'<strong>'+p.children.length+' 份子档案</strong><div class="tiny">'+p.children.map(c=>esc(c.name)).join('、')+'</div>',`${esc(r.method)}<div class="tiny muted">${esc(r.trigger)}</div>`,esc(r.store),mrBadge(status),`<div class="mr-row-actions">${btn('详情',`mrOpen('record',${mrQuote(r.id)})`,'text')}${mrTime(r.coolingUntil)>Date.now()&&!r.revoked&&!r.followUp&&!c?btn('撤销',`mrUndoAsk(${mrQuote(r.id)})`,'text'):c?btn('纠错工单',`mrGoCorrection(${mrQuote(r.id)})`,'text'):['已合并','部分已纠错'].includes(status)?btn('发起纠错',`mrStartCorrection(${mrQuote(r.id)})`,'text'):status==='快照已归档'?btn('手工调账',`mrArchived(${mrQuote(r.id)})`,'text'):''}</div>`]}))+(!rows.length?empty('暂无符合条件的数据','调整搜索条件或重置后再试。'):'')+`<div class="pagination"><span>共 ${all.length} 条</span><div class="actions">${btn('上一页',`mrTurnPage(${mrPage-1})`)}<span>${mrPage} / ${pages}</span>${btn('下一页',`mrTurnPage(${mrPage+1})`)}</div></div>`}
function mrToggleSelected(id,checked){checked?mrSelected.add(id):mrSelected.delete(id);let el=$('#mrSelectedSummary');if(el)el.textContent=mrSelected.size?' · 已选 '+mrSelected.size+' 条':''}
function mrTurnPage(n){let max=Math.max(1,Math.ceil(mrRows().length/7));mrPage=Math.max(1,Math.min(n,max));render()}
function mrCustomerBrief(c){return `${pcPersonLink(c)}<div class="tiny muted mono">${c.id}</div><div class="tiny muted">${esc(c.phone||'无手机号')}</div>`}
function mrCurrent(){if(mrTask?.kind==='customer')return pcCustomers().find(c=>c.id===mrTask.id);return mrTask?.kind==='candidate'?mcDetailRecord(state.mergeCandidates.find(g=>g.id===mrTask.id)):mrTask?.kind==='record'?state.mergeRecords.find(r=>r.id===mrTask.id):state.mergeApplications.find(r=>r.id===mrTask?.id)}
function mrOpen(kind,id){if(kind==='application'&&apItem('merge',id)?.review){apOpen('merge',id);return}if(kind==='customer'){pcOpenCustomer(id);return}pcRecordModalState=null;closeModal();let r=(kind==='record'?state.mergeRecords:state.mergeApplications).find(r=>r.id===id);if(!r)return;mrFocus=document.activeElement;let draft=kind==='application'&&r.status==='待审核'?state.mergeReviewDrafts?.[id]:null;mrTask={kind,id,tab:draft?.tab||'overview',plan:clone(draft?.plan||r.plan),dirty:false};if(draft){mrTask.applicationEdit=clone(draft.form);mrTask.inspectCustomerId=draft.inspectCustomerId||''}if(kind==='application'&&!MA_STEPS.some(x=>x[0]===mrTask.tab)){if(r.status==='待审核')mrTask.tab='compare';else if(r.status==='已通过')mrTask.tab='confirm'}render();$('#mergeRecordPanel .icon-btn')?.focus()}
function mrEligible(c){return c.status!=='已合并-从属'}
function mrAvailablePair(){let customers=state.mergeCustomers;for(let i=0;i<customers.length-1;i+=2){let pair=[customers[i],customers[i+1]],key=mrPairKey(pair);if(!pair.every(mrEligible))continue;if(!state.mergeExcludedPairs.includes(key)&&!state.mergeApplications.some(a=>['待审核','已通过','执行失败'].includes(a.status)&&mrPairKey(a.pair)===key)&&!state.mergeRecords.some(r=>!r.revoked&&mrPairKey(r.pair)===key))return clone(pair)}return clone(customers.slice(0,2))}
const MA_STEPS=[['compare','确定主档案'],['plan','处理进行中订单'],['confirm','合并确认']];
const MA_FIELDS=[['姓名','name'],['性别','gender'],['生日','birthday'],['备注','remark']];
function maDraftLabel(){if(!maEditable())return mgAppStatus(maRecord());return mrTask.dirty?'有未保存修改':mrTask.kind==='new'?(mrTask.savedAt?'草稿已保存':'未提交'):state.mergeReviewDrafts?.[mrTask.id]?'核对草稿已保存':mrTask.editingPlan?'编辑已保存方案':'待核实'}
