function maRequireMain(r=maRecord()){if(maHasMain(r))return true;mrTask.tab='compare';render();toast('请先在客户卡片中设为主档案');return false}
function maGoStep(key){if(key==='overview')key='compare';let r=maRecord();if(!MA_STEPS.some(x=>x[0]===key))return;if(key!=='compare'&&r.pair.length<2){toast('请先选择至少 2 份需要合并的档案');return}if(key!=='compare'&&!maRequireMain(r))return;mrTask.tab=key;render();$('#mergeRecordPanel .merge-drawer-body')?.scrollTo(0,0);$('#mergeRecordPanel .ma-steps [aria-selected="true"]')?.focus()}
function maStepKey(e,i){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let length=MA_STEPS.length,n=e.key==='Home'?0:e.key==='End'?length-1:(i+(e.key==='ArrowRight'?1:-1)+length)%length;maGoStep(MA_STEPS[n][0])}
function maContext(r){let main=r.pair.find(c=>c.id===mrTask.plan.mainId);return `<div class="ma-context"><span class="muted">参与档案</span><strong>${r.pair.map(c=>esc(c.name)).join(' + ')||'尚未选择'}</strong>${main?`<span class="muted">→ 主档案</span><strong>${esc(main.name)} · ${uiId(main.id)}</strong>`:''}</div>`}
function maDrawer(r){let editable=maEditable();if(editable){maPrepare(r);maForm(r)}let key=MA_STEPS.some(x=>x[0]===mrTask.tab)?mrTask.tab:editable?'compare':'confirm';if(!maHasMain(r)||r.pair.length<2)key='compare';mrTask.tab=key;let ready=r.pair.length>=2&&maHasMain(r),step=MA_STEPS.findIndex(x=>x[0]===key),isNew=mrTask.kind==='new',title=isNew&&!r.candidateId?'申请合并':'核对合并方案';
 let content=key==='compare'?maCompareUI(r):key==='plan'?maOrdersUI(r,editable):maConfirmUI(r,editable);
 let next=step<MA_STEPS.length-1?btn(['处理进行中订单','确认合并信息'][step],`maGoStep('${MA_STEPS[step+1][0]}')`,'primary'):editable?btn(isNew&&!r.candidateId?'提交审批':'提交审批','maSubmit()','primary'):btn('执行合并','mrExecuteAsk()','primary');
 let left=editable?btn('取消','mrClose()')+(isNew?btn('保存草稿','maSaveDraft()'):btn('保存草稿','maSavePendingDraft()')):btn('关闭','mrClose()')+btn(state.mergeReviewDrafts?.[r.id]?'继续修改':'修改方案','mgEditPlan()');
 if(!ready)next=next.replace('<button ','<button disabled aria-describedby="ma-main-hint" ');
 return `<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector('#modal>[data-overlay-layer]'))mrClose()"><section id="mergeRecordPanel" class="merge-drawer ma-composer" role="dialog" aria-modal="true" aria-label="${title}"><header class="merge-drawer-head"><div class="ma-heading"><h2>${title}</h2><span>${maDraftLabel()}</span></div><button class="icon-btn" aria-label="关闭合并申请" onclick="mrClose()">${icon('close')}</button></header><div class="ma-steps" role="tablist" aria-label="合并申请步骤">${MA_STEPS.map(([k,t],i)=>`<button id="ma-step-${k}" role="tab" ${k!=='compare'&&!ready?'disabled':''} aria-controls="ma-active-step" aria-selected="${key===k}" tabindex="${key===k?0:-1}" class="${key===k?'active':step>i?'done':''}" onclick="maGoStep('${k}')" onkeydown="maStepKey(event,${i})"><span>${i+1}</span>${t}</button>`).join('')}</div><div class="merge-drawer-body" data-drawer-scroll="merge-application"><div id="ma-active-step" role="tabpanel" aria-labelledby="ma-step-${key}">${key==='plan'?maContext(r):''}${content}</div></div><footer class="merge-drawer-foot"><div class="actions">${left}</div><div class="actions">${!ready?'<span id="ma-main-hint" class="ma-note">'+(r.pair.length<2?'请至少选择两份客户档案':'请先在卡片中设为主档案')+'</span>':''}${step?btn('上一步',`maGoStep('${MA_STEPS[step-1][0]}')`):''}${next}</div></footer></section></div>`;
}
function maParticipantsUI(r){return maCompareUI(r)}
function maPerson(c){return '<strong>'+esc(c.name)+'</strong><div class="ma-caption">ID '+uiId(c.id)+(c.mergeApplicationExample?' · 示例':'')+'</div>'}
function maDetectionNote(r){let g=state.mergeCandidates.find(x=>x.id===r.candidateId),reasons=r.reasons||g?.hits?.map(x=>x.reason)||[];return `<div class="ma-detection"><span>${esc(reasons.length?'待核实：'+[...new Set(reasons)].join('；'):g?.basis||'人工申请，核实档案与订单后保存方案')}</span>${r.candidateId?btn('检测依据','maViewDetection()','text'):''}</div>`}
function maViewDetection(){let r=maRecord();modal('合并检测依据',mgDetection(r),btn('返回合并方案','closeModal()'),true)}
function maViewHistory(){modal('申请与操作记录',mgRequestNotes(maRecord())+mgHistory(maRecord()),btn('返回合并方案','closeModal()'),true)}
function maOrderInfo(c,o){return {name:o.name||o.projectName||(o.items||[]).map(x=>x.name).filter(Boolean).join('、')||'未记录项目',store:o.store||o.receptionStore||'',bookingBy:o.bookingBy||o.appointmentBy||o.scheduler||'',receiver:o.receiver||o.receptionist||o.receptionEmployee||'',created:o.createdAt||o.created||o.at||'',appointment:o.appointmentAt||o.scheduledAt||'',arrived:o.arrivedAt||o.checkinAt||'',paid:o.paidAt||''}}
function maAllOrders(r){return r.pair.flatMap(c=>(c.orders||[]).map(o=>({c,o,info:maOrderInfo(c,o)})))}
function maFocusCustomer(){let card=$('#mergeRecordPanel .ma-customer-card.is-selected');card?.querySelector('[data-card-select]')?.focus({preventScroll:true});card?.scrollIntoView({block:'nearest',inline:'nearest'})}
function maBrowseCustomer(id){if(!maRecord().pair.some(c=>c.id===id))return;mrTask.inspectCustomerId=id;render();maFocusCustomer()}
function maCustomerCardKey(e,i){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let pair=maRecord().pair,n=e.key==='Home'?0:e.key==='End'?pair.length-1:(i+(e.key==='ArrowRight'?1:-1)+pair.length)%pair.length;maBrowseCustomer(pair[n].id)}
function maChooseMain(id){if(mrTask.inspectCustomerId!==id)return;maSetMain(id);maFocusCustomer()}
function maCustomerCard(r,c,i,selected,canSelect){let isMain=mrTask.plan.mainId===c.id,spares=[...new Set([c.oldPhone,...(c.phones||[])].filter(x=>x&&x!==c.phone))].map(uiPhone).join('、');
 let rows=[['手机号',uiPhone(c.phone)||'未填写'],['备用手机',spares||'未填写'],['门店',c.store||'未记录'],['归属客服',c.consultant||'未记录'],['性别 / 生日',[c.gender,c.birthday].filter(Boolean).join(' / ')||'未填写'],['建档时间',c.created||'未记录'],['白条 / 充值',money(c.white)+' / '+money(c.recharge)]];
 let identities=[['UnionID',[...new Set([c.unionId,...(c.unionIds||[])].filter(Boolean))].join('、')||'未记录'],['企微 ID',[...new Set([c.externalId,...(c.externalIds||[])].filter(Boolean))].join('、')||'未记录'],['备注',c.remark||'未填写']];
 return `<article class="ma-customer-card ${selected?'is-selected':''}" aria-label="${esc(c.name)}的客户资料" onclick="if(!event.target.closest('button,a,input,select,textarea,label'))maBrowseCustomer(${esc(mrQuote(c.id))})"><div class="ma-card-head"><button type="button" data-card-select aria-label="查看${esc(c.name)} ${uiId(c.id)}的全部订单" aria-pressed="${selected}" aria-controls="ma-customer-orders" tabindex="${selected?0:-1}" onclick="maBrowseCustomer(${esc(mrQuote(c.id))})" onkeydown="maCustomerCardKey(event,${i})"><strong>${esc(c.name)}</strong><span>ID ${uiId(c.id)}</span></button>${isMain?'<span class="ma-card-main">主档案</span>':''}</div><dl class="ma-card-details">${rows.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+esc(value)+'</dd></div>').join('')}</dl><dl class="ma-card-identities">${identities.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+esc(value)+'</dd></div>').join('')}</dl><div class="ma-card-foot">${selected?(canSelect?btn('移除',`mrRemoveMember(${mrQuote(c.id)})`,'text'):'<span></span>'):'<span class="ma-note">点击查看订单</span>'}${selected?(isMain?'<span class="ma-card-current">当前主档案</span>':maEditable()?btn('设为主档案',`maChooseMain(${mrQuote(c.id)})`,'ma-set-main'):''):''}</div></article>`;
}
function maCompareUI(r){let canSelect=mrTask.kind==='new',c=r.pair.find(x=>x.id===mrTask.inspectCustomerId)||r.pair[0];mrTask.inspectCustomerId=c?.id||'';
 let toolbar=`<div class="ma-customer-toolbar"><div class="actions"><span>参与客户</span>${canSelect?btn(r.pair.length?'添加客户':'选择客户','mrPick(-1)'):maEditable()?btn('调整客户',`mrNew(${mrQuote(r.id)})`):''}<span class="ma-note">${r.pair.length?'已选 '+r.pair.length+' 份档案':'选择需要合并的客户'}</span></div><div class="actions">${r.candidateId?btn('检测依据','maViewDetection()','text'):''}${canSelect?'':btn('申请与操作记录','maViewHistory()','text')}</div></div>`;
 if(!c)return toolbar+'<div class="ma-browse-empty">选择客户后，可通过资料卡片切换查看订单。</div>';
 let cards='<div class="ma-customer-cards" role="group" aria-label="切换客户资料">'+r.pair.map((x,i)=>maCustomerCard(r,x,i,x.id===c.id,canSelect)).join('')+'</div>';
 let orders=maAllOrders(r).filter(x=>x.c.id===c.id).sort((a,b)=>Number(mrActive(b.o))-Number(mrActive(a.o)));
 let list=contentModule('全部订单',orders.length?maOrderTable(r,orders,false,true):'<div class="ma-no-orders">此客户暂无订单</div>','<span class="ma-note">'+esc(c.name)+' · '+uiId(c.id)+'<span class="ma-order-sort-note">进行中订单优先</span></span>','ma-orders ma-customer-orders');
 return toolbar+cards+`<div id="ma-customer-orders" role="region" aria-label="${esc(c.name)}的全部订单">`+list+'</div>';
}
function maOrderTable(r,rows,editable=false,comparison=false){let p=mrTask.plan,returnedIds=new Set(r.pair.length?mrImpact(r.pair,p).returned.map(o=>o.id):[]);let heads=['订单 / 来源档案','状态 / 预约金','门店 / 人员','关键时间',comparison?'操作':'合并处理',...(comparison?[]:['依据 / 详情'])];return table(heads,rows.map(({c,o,info})=>{
 let active=mrActive(o),returned=active&&returnedIds.has(o.id);
 let title='<strong>'+esc(info.name)+'</strong><div class="ma-caption">订单 '+uiId(o.id)+'</div><div class="ma-caption">'+esc(c.name)+(c.id===p.mainId?' · 主档案':'')+'</div>';
 let status=badge(o.status)+'<div class="ma-caption">预约金 '+money(o.deposit||0)+'</div><div class="ma-caption">订单 '+money(o.amount||0)+'</div>';
 let people=esc(info.store||'订单门店未记录')+'<div class="ma-caption">预约：'+esc(info.bookingBy||'未记录')+'</div><div class="ma-caption">接待：'+esc(info.receiver||'未记录')+'</div>';
 let time='<div class="ma-date">预约 '+esc(info.appointment||'未安排')+'</div><div class="ma-caption">'+(o.status==='已到店'?'到店 '+esc(info.arrived||'未记录'):'创建 '+esc(info.created||'未记录'))+'</div><div class="ma-caption">'+(Number(o.deposit)>0?'付预约金 '+esc(info.paid||'未记录'):'无预约金支付')+'</div>';
 if(comparison)return [title,status,people,time,btn('订单详情',`maOrderDetail(${mrQuote(c.id)},${mrQuote(o.id)})`,'text')];
 let action=editable&&active?select([['keep','保留订单'],['return','合并流退']],returned?'return':'keep',`aria-label="订单 ${uiId(o.id)} 合并处理" onchange="mrSetOrder(${esc(mrQuote(o.id))},this.value)"`):esc(active?(returned?'合并流退':'保留订单'):'历史订单保留');
 let effect=returned?(o.status==='已排客'&&(o.scheduledAt||o.appointmentAt)?'取消排客 '+(o.scheduledAt||o.appointmentAt):o.status==='已到店'?'到店合并流退，保留到店历史':'无排客安排需要取消'):(active?'保持原状态、人员及预约':'原订单终态不变');
 action+='<div class="ma-caption">'+esc(effect)+'</div>';
 let reason=editable&&active?`<input aria-label="订单 ${uiId(o.id)} 处理依据" placeholder="处理依据（选填）" value="${esc(p.orderReasons?.[o.id]||'')}" oninput="mrTask.plan.orderReasons[${esc(mrQuote(o.id))}]=this.value;maMarkDirty()">`:(p.orderReasons?.[o.id]?'<div>'+esc(p.orderReasons[o.id])+'</div>':'');
 return [title,status,people,time,action,reason+btn('订单详情',`maOrderDetail(${mrQuote(c.id)},${mrQuote(o.id)})`,'text')];
 }))+(rows.length?'':body('<div class="ma-empty">暂无符合条件的订单。</div>'))}
function maOrdersUI(r,editable=true){let rows=maAllOrders(r).filter(x=>mrActive(x.o));return contentModule('进行中订单处理',maOrderTable(r,rows,editable),'','ma-orders')+body('<p class="ma-note">历史订单全部保留。流退订单保留原记录和支付流水，不自动退款；原销售及服务员工不随主档案选择而改变。</p>')}
function maOrderDetail(cid,id){let r=maRecord(),c=r.pair.find(c=>c.id===cid),o=c?.orders.find(o=>o.id===id);if(!o)return;let i=maOrderInfo(c,o),payments=mrPayments(c).filter(x=>x.orderId===id);modal('订单详情',body(kv({'来源档案':esc(c.name)+' · '+uiId(c.id),'订单':uiId(o.id)+' · '+esc(i.name),'当前状态':esc(o.status),'订单门店':esc(i.store||'未记录'),'预约人员':esc(i.bookingBy||'未记录'),'接待人员':esc(i.receiver||'未记录'),'归属客服':esc(o.consultant||'未记录'),'创建时间':esc(i.created||'未记录'),'预约 / 排客时间':esc(i.appointment||'未安排'),'到店时间':esc(i.arrived||'未记录'),'预约金支付时间':esc(i.paid||'未记录'),'订单金额':money(o.amount||0),'预约金':money(o.deposit||0)})))+contentModule('关联支付流水',table(['流水','类型','金额','时间'],payments.map(x=>[uiId(x.id),esc(x.type),cxSign(pcPaymentAmount(x)),esc(x.at||'未记录')]))+(payments.length?'':body('<p class="small muted">未记录关联支付流水。</p>')),btn('返回合并方案','closeModal()'),true)}
function maProfileDetail(id){let c=maRecord().pair.find(c=>c.id===id);if(!c)return;modal('参与合并的客户档案',body(kv({'客户':esc(c.name)+' · '+uiId(c.id),'手机号':esc(uiPhone(c.phone)),'备用手机号':esc(uiPhone(c.oldPhone)||'未填写'),'门店':esc(c.store),'归属客服':esc(c.consultant),'性别 / 生日':esc([c.gender,c.birthday].filter(Boolean).join(' / ')),'建档时间':esc(c.created),'备注':esc(c.remark||'未填写')}))+table(['订单','项目','状态','预约时间'],(c.orders||[]).map(o=>[uiId(o.id),esc(maOrderInfo(c,o).name),esc(o.status),esc(maOrderInfo(c,o).appointment||'未安排')])),btn('返回参与档案','closeModal()'),true)}
function maBasicUI(r,editable){let impact=mrImpact(r.pair,mrTask.plan),after=impact.after,fieldRow=(label,key,control,wide=false)=>`<div class="ma-basic-field ${wide?'ma-basic-wide':''}"><label for="ma-field-${key}">${label}</label><div class="ma-field-control">${control}</div></div>`,valueUI=(key)=>`<div class="ma-field-value" id="ma-field-${key}">${esc(after[key]||'未填写')}</div>`;
 let input=(key,label,type='text')=>editable?`<input id="ma-field-${key}" type="${type}" aria-label="合并后${label}" value="${esc(after[key]||'')}" ${key==='remark'?'placeholder="备注（选填）"':''} oninput="maSetProfile('${key}',this.value)">`:valueUI(key);
 let gender=editable?`<select id="ma-field-gender" aria-label="合并后性别" onchange="maSetProfile('gender',this.value)">${[...new Set(['','女','男',after.gender||''])].map(x=>`<option value="${esc(x)}" ${x===(after.gender||'')?'selected':''}>${esc(x||'未填写')}</option>`).join('')}</select>`:valueUI('gender');
 let phones=maIdentityRows(r.pair).filter(x=>x.type==='phone'),phone=editable&&phones.length?`<select id="ma-field-phone" aria-label="合并后主手机号" onchange="maSetPhone(this.value)">${phones.map(x=>`<option value="${esc(x.value)}" ${x.value===after.phone?'selected':''}>${esc(x.value)} · ${x.sources.map(c=>esc(c.name)).join(' / ')}</option>`).join('')}</select>`:valueUI('phone'),secondary=phones.filter(x=>x.value!==after.phone);
 let fields=fieldRow('姓名','name',input('name','姓名'))+fieldRow('主手机号','phone',phone)+fieldRow('性别','gender',gender)+fieldRow('生日','birthday',input('birthday','生日','date'))+fieldRow('备注','remark',input('remark','备注'),true)+(secondary.length?`<div class="ma-basic-field ma-basic-wide ma-phone-secondary-field"><label>备用手机号</label><div class="ma-phone-secondary">${secondary.map(x=>`<span title="${esc(x.sources.map(c=>c.name+' · '+uiId(c.id)).join('、'))}">${esc(x.value)}</span>`).join('')}<small>其余号码作为备用保留</small></div></div>`:'');
 let meta=[['保留档案',uiId(impact.main.id)],['门店',after.store||'未记录'],['客服',after.consultant||'未记录'],['客户类型',impact.type]];
 return contentModule('合并后客户资料','<dl class="ma-basic-meta">'+meta.map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div class="ma-basic-fields">'+fields+'</div>','','ma-basic-section')}
function maApplicationForm(r,editable){let f=editable?maForm(r):r;return contentModule('申请原因与依据',editable?'<div class="ma-form">'+field('申请原因',select(['客户更换手机号','同一客户重复建档','微信与手机号档案重复','其他'],f.reasonType||'同一客户重复建档','aria-label="合并申请原因" onchange="maForm().reasonType=this.value;maMarkDirty()"'))+field('核实说明',`<textarea rows="3" aria-label="合并核实说明" placeholder="填写确认这些档案属于同一人的依据（选填）" oninput="maForm().reason=this.value;maMarkDirty()">${esc(f.reason||'')}</textarea>`)+field('核实材料',`<div><label class="btn">上传材料<input type="file" multiple hidden aria-label="上传合并核实材料" onchange="maAddFiles(this.files)"></label>${(f.evidence||[]).map((file,i)=>`<div class="file-row"><span class="flex1">${esc(file)}</span>${btn('移除',`maForm().evidence.splice(${i},1);maMarkDirty();render()`,'text')}</div>`).join('')}</div>`)+ '</div>':body(kv({'申请原因':esc(f.reasonType||'人工核实'),'核实说明':esc(f.reason||'未填写'),'核实材料':(f.evidence||[]).map(esc).join('、')||'未上传'})))}
function maAddFiles(files){let f=maForm();for(let file of Array.from(files)){if(!f.evidence.includes(file.name))f.evidence.push(file.name);fileObjects.set('merge:'+file.name,file)}maMarkDirty();render()}
function maConfirmUI(r,editable){if(r.pair.length<2)return maParticipantsUI(r);let p=mrTask.plan,impact=mrImpact(r.pair,p);return maBasicUI(r,editable)+contentModule('订单处理结果',`<div class="ma-result-counts"><span>保留 ${impact.kept.length} 笔订单</span><span>流退 ${impact.returned.length} 笔进行中订单</span><span>取消 ${impact.cancelled.length} 条排客</span></div>`+maOrderTable(r,maAllOrders(r),false),'','ma-orders')+contentModule('其他业务保留情况',table(['业务','合并后结果','处理方式'],[['支付流水',impact.after.payments.length+' 笔 · '+money(impact.totalPayments),'原收款、退款及订单关联完整保留'],['白条 / 充值余额',money(impact.after.white)+' / '+money(impact.after.recharge),'余额及原流水并入主档案'],['加微 / 标签',impact.after.wechat.length+' 条加微 · '+impact.after.tags.length+' 个标签','去重保留，原始来源可追溯'],['售后 / 通话 / 影像',(impact.after.tickets||[]).length+' / '+(impact.after.calls||[]).length+' / '+(impact.after.images||[]).length,'原记录及关联关系保留']]))+maApplicationForm(r,editable)+body('<p class="ma-note">'+(editable?'本次提交完整方案审批，审批通过后由系统合并档案和订单。':'执行采用已保存方案；原档案快照和每笔处理结果均保留。')+'</p>')}
function maSubmit(){if(!maEditable())return;let r=maRecord();if(r.pair.length<2){maGoStep('overview');toast('请至少选择 2 份不同档案');return}maPrepare(r);if(!maRequireMain(r))return;if(mrTask.kind==='new'){if(r.candidateId)mgSaveDetectedPlan();else mrSubmit()}else{mrApprove();if(mrCurrent()?.status==='已通过'){mrTask.tab='confirm';render()}}}
