function mrImpactSummary(r,plan){let p=mrImpact(r.pair,plan);return `<div class="mr-impact-grid">${kv({'主档案':esc(p.after.name)+' · '+p.main.id,'待并入档案':p.children.length+' 份，原档案保留并标记从属','合并后客户类型':p.type,'归属客服':esc(p.after.consultant)})}${kv({'保留订单':p.kept.length+' 笔（含历史订单）','流退进行中订单':p.returned.length+' 笔','取消排课':p.cancelled.length+' 条','保留支付记录合计':money(p.totalPayments)})}</div>${p.returned.length?`<div style="margin-top:16px">${table(['将流退订单','所属档案','当前状态','流退类型','人头变化 / 考核'],p.returned.map(o=>[o.id,esc(r.pair.find(c=>c.id===o.origin)?.name||o.origin),o.status,o.status==='已到店'?'合并到店流退':'合并预约流退',esc(o.consultant)+' · '+(o.status==='已到店'?'到店':'预约')+'人头 −1（合并流退不纳入考核）']))}</div>`:'<p class="mr-inline-note">无订单需要流退，历史订单全部迁入主档案。</p>'}<p class="mr-inline-note">覆盖全部 ${r.pair.length} 份档案。支付流水不删除，不自动退款，不跨订单转移预约金；全部档案快照、订单来源与身份标识共同留存。</p>`+pcPeopleImpact({...r,snapshot:{after:p.after}})}
const MH_TABS=[['overview','合并结果'],['orders','订单处理'],['changes','数据迁移'],['compare','合并前快照'],['logs','操作记录']];
function mhData(r){return {before:r.snapshot?.before||r.pair||[],after:r.snapshot?.after||null}}
function mhArchived(r){return r.archived||mrTime(r.retainUntil)<Date.now()}
function mhInfo(rows){return '<dl class="mh-info">'+rows.map(([label,value,wide])=>'<div'+(wide?' class="mh-wide"':'')+'><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl>'}
function mhText(value){return esc(value===0?0:value||'未记录')}
function mhProfile(c,title,snapshot=false){let phones=[...new Set([c.oldPhone,...(c.phones||[])].filter(x=>x&&x!==c.phone))],rows=[['姓名',mhText(c.name)],['主手机号',mhText(c.phone)],['性别',mhText(c.gender)],['生日',mhText(c.birthday)],['档案门店',mhText(c.store)],['归属客服',mhText(c.consultant)],['档案 ID',uiId(c.id)],['客户类型',mhText(c.customerType)],['备注',mhText(c.remark),true]];if(phones.length)rows.push(['备用手机号',phones.map(esc).join('　'),true]);if(snapshot)rows.push(['建档时间',mhText(c.created)],['白条 / 充值',(c.white==null?'未记录':money(c.white))+' / '+(c.recharge==null?'未记录':money(c.recharge))],['UnionID',mhText([...new Set([c.unionId,...(c.unionIds||[])].filter(Boolean))].join('、')),true],['企微 ID',mhText([...new Set([c.externalId,...(c.externalIds||[])].filter(Boolean))].join('、')),true]);return contentModule(title,mhInfo(rows),'','mh-profile')}
function mhRelation(r){let {before,after}=mhData(r);return '<div class="mh-relation"><strong>'+before.map(c=>esc(c.name)).join(' + ')+'</strong><span>→</span><strong>'+esc(after?.name||'结果未保存')+'</strong></div><div class="mh-meta"><span>记录 ID '+uiId(r.id)+'</span><span>'+esc(r.method)+'</span><span>'+esc(r.time)+'</span><span>'+esc(r.author)+'</span></div>'}
function mhNote(r){return r.revoked?'<p class="mh-state-note"><strong>已撤销</strong> · '+esc(r.revokedAt||'撤销时间未记录')+'。下方保留当次合并的历史结果，参与档案已恢复独立。</p>':(r.followUp||mrCorrection(r))?'<p class="mh-state-note">下方为本次执行时的结果；后续业务和纠错变更请在当前客户档案中查看。</p>':''}
function mhTabs(r,key,nested=false){let prefix=nested?'mh-nested':'mh-record';return `<div class="mh-tabs" role="tablist" aria-label="合并记录分类">${MH_TABS.map(([k,t],i)=>`<button id="${prefix}-${k}" role="tab" aria-controls="${prefix}-content" aria-selected="${key===k}" tabindex="${key===k?0:-1}" class="${key===k?'active':''}" onclick="mhSetTab(${esc(mrQuote(r.id))},'${k}',${nested})" onkeydown="pcRecordTabKey(event,${i})">${t}</button>`).join('')}</div>`}
function mhSetTab(id,key,nested=false){if(!MH_TABS.some(x=>x[0]===key))return;if(nested){pcViewRecord(id,key);return}if(mrTask?.kind!=='record'||mrTask.id!==id)return;mrTask.tab=key;render();$('#mergeRecordPanel .merge-drawer-body')?.scrollTo(0,0);$('#mh-record-'+key)?.focus()}
function mhPickSnapshot(id,cid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r||!mhSnapshotPeople(r).some(c=>c.id===cid)||!mhCanViewSnapshot(r))return;if(nested){pcRecordModalState={...(pcRecordModalState||{}),id,tab:'compare',snapshotId:cid};pcViewRecord(id,'compare')}else{mrTask.snapshotId=cid;mhSetTab(id,'compare')}}
