function mhOrderAction(x){return !x.after?'结果未保存':!x.before?'原状态未保存':mhReturned(x)?'合并流退':mrActive(x.before)?'保留订单':'历史订单保留'}
function mhAppointment(x){let a=x.before?.appointmentAt||x.before?.scheduledAt||'',b=x.after?.appointmentAt||x.after?.scheduledAt||'';if(!x.after)return '结果未保存';if(x.before&&(a&&!b||x.after.scheduleStatus==='合并取消'&&x.before.scheduleStatus!=='合并取消'))return '已取消'+(a?' · '+a:'');if(x.after.scheduleStatus==='合并取消')return '原排客已取消';if(x.before&&!mrActive(x.before))return a||b?'历史记录 · '+(b||a):'无排客记录';return b?'保留 · '+b:x.before?'未安排':'原排客信息未保存'}
function mhOrders(r,nested=false){if(mhArchived(r))return mhUnavailable();let rows=mhOrderRows(r),sorted=rows.slice().sort((a,b)=>Number(mrActive(b.before||b.after))-Number(mrActive(a.before||a.after))),returned=rows.filter(mhReturned),cancelled=rows.filter(x=>mhAppointment(x).startsWith('已取消')),summary='<div class="mh-meta"><span>保留 '+rows.filter(x=>x.after&&!mhReturned(x)).length+' 笔订单</span><span>合并流退 '+returned.length+' 笔</span><span>取消 '+cancelled.length+' 条排客</span>'+(rows.some(x=>!x.after)?'<span>部分订单结果未保存</span>':'')+'</div>';
 return contentModule('订单处理结果',summary+table(['订单 / 来源档案','合并前业务','门店 / 人员','关键时间','执行结果','操作'],sorted.map(x=>{let o=x.before||x.after,c=x.c,info=maOrderInfo(c||{},o);return [esc(info.name)+'<div class="ma-caption">订单 '+uiId(o.id)+'</div><div class="ma-caption">'+(c?esc(c.name)+' · '+uiId(c.id):'来源未保存')+'</div>',(x.before?badge(o.status):'原状态未保存')+'<div class="ma-caption">预约金 '+money(o.deposit||0)+'</div><div class="ma-caption">订单 '+money(o.amount||0)+'</div>',mhText(info.store)+'<div class="ma-caption">预约：'+mhText(info.bookingBy)+'</div><div class="ma-caption">接待：'+mhText(info.receiver)+'</div>','<div>预约 '+esc(info.appointment||'未安排')+'</div><div class="ma-caption">创建 '+mhText(info.created)+'</div><div class="ma-caption">到店 '+mhText(info.arrived)+'</div>',mhOrderAction(x)+'<div class="ma-caption">'+(x.after?'合并后 '+esc(x.after.status):'')+'</div><div class="ma-caption">'+esc(mhAppointment(x))+'</div>',btn('订单详情',`mhOrderDetail(${mrQuote(r.id)},${mrQuote(o.id)},${nested})`,'text')]}))+(rows.length?'':'<p class="mh-empty">本次快照无订单记录。</p>'),'','mh-orders')}
function mhOrderDetail(id,oid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r||mhArchived(r))return;let x=mhOrderRows(r).find(x=>(x.before||x.after).id===oid);if(!x)return;let o=x.before||x.after,info=maOrderInfo(x.c||{},o),after=mhData(r).after,payments=(after?.payments||[]).filter(p=>p.orderId===oid),tab=nested?pcRecordModalState?.tab||'orders':mrTask?.tab||'orders';mhDetail(r,'订单处理详情',contentModule('订单与处理结果',mhInfo([['订单',uiId(oid)+' · '+esc(info.name)],['来源档案',x.c?esc(x.c.name)+' · '+uiId(x.c.id):'未保存'],['合并前状态',mhText(x.before?.status)],['合并后状态',mhText(x.after?.status)],['订单门店',mhText(info.store)],['订单金额',money(o.amount||0)],['预约人员',mhText(info.bookingBy)],['接待人员',mhText(info.receiver)],['合并前客服',mhText(x.before?.consultant)],['合并后客服',mhText(x.after?.consultant)],['创建时间',mhText(info.created)],['预约金支付',mhText(info.paid)],['到店时间',mhText(info.arrived)],['排客处理',esc(mhAppointment(x))],['处理依据',mhText(r.plan.orderReasons?.[oid]),true]]))+contentModule('关联支付流水',table(['流水 ID','类型','金额','发生时间'],payments.map(p=>[uiId(p.id),mhText(p.type),cxSign(pcPaymentAmount(p)),mhText(p.at)]))+(payments.length?'':'<p class="mh-empty">快照未保存关联支付流水。</p>')),nested,tab)}
function mhMigration(r,nested=false){let after=mhData(r).after,summary=contentModule('数据迁移结果',table(['数据类型','数量','执行结果'],(r.migrations||[]).map(m=>[esc(m.name),esc(m.count),esc(m.detail)])),!mhArchived(r)&&after?btn('逐条迁移明细',`mhMigrationDetail(${mrQuote(r.id)},${nested})`,'text'):'');if(mhArchived(r)||!after)return mhUnavailable()+summary;let before=mhData(r).before,checks=r.reconciliation||pcReconciliation(before,after);return summary+contentModule('数据完整性',table(['核对项','合并前应有值','合并后值','结果'],checks.map(x=>[esc(x.label),x.expected===null?'未保存明细':esc(x.expected),esc(x.actual),badge(x.status,x.ok?'green':'orange')]))+(r.evidenceVersion===1?'':'<p class="mh-footnote">按已保存快照对照；历史记录未保存执行时的核对报告。</p>'),btn('统计与人头变化',`mhStatsDetail(${mrQuote(r.id)},${nested})`,'text'))}
function mhMigrationDetail(id,nested=false){let r=state.mergeRecords.find(r=>r.id===id);if(!r||mhArchived(r))return;mhDetail(r,'逐条迁移明细',pcMigrationTable(r),nested,'changes')}
function mhStatsDetail(id,nested=false){let r=state.mergeRecords.find(r=>r.id===id);if(!r||mhArchived(r)||!mhData(r).after)return;mhDetail(r,'统计与人头变化',pcStatsTable([mhData(r).after])+pcPeopleImpact({...r,pair:mhData(r).before}),nested,'changes')}
function mhEnsureSnapshotExamples(r){
 if(!r?.demo)return false;if(r.snapshotExamples?.version===1&&r.snapshotExamples.recordId===r.id)return false;
 let before=mhData(r).before;if(!before.length)return false;
 r.snapshotExamples={version:1,recordId:r.id,before:before.map((original,index)=>{
  let c=clone(original);if(qaComplete(c)&&c.payments?.length)return c;
  let prefix='SNAP-'+r.id+'-'+c.id,id=key=>prefix+'-'+key,base=mrTime(r.time),at=days=>mrDate(base-days*86400000),store=c.store||'A01 · 静安店',staff=c.consultant||'顾问陈',teacher=['护理师王','护理师许','护理师刘'][index%3];
  let row=(key,values)=>({id:id(key),snapshotExample:true,...values});
  for(let key of ['orders','payments','assets','walletAccounts','serviceRecords','followups','performanceEntries'])c[key]||=[];
  let order=row('ORDER',{name:'面部护理套餐',status:'已完成',amount:1500,deposit:300,store,consultant:staff,bookingBy:staff,receiver:teacher,createdAt:at(12),paidAt:at(12),scheduledAt:at(10),arrivedAt:at(10),customerType:'老客'});
  let asset=row('ASSET',{name:'面部护理权益',orderId:order.id,purchased:6,gifted:0,consumed:2,refunded:0,expired:0,remaining:4,frozen:0,unit:'次',unitValue:250});
  c.orders.push(order);c.assets.push(asset);
  c.payments.push(row('DEPOSIT',{orderId:order.id,type:'预约金收取',amount:300,at:at(12),status:'已完成'}),row('PAYMENT',{orderId:order.id,type:'订单尾款',amount:700,at:at(11),status:'已完成'}));
  let opening=c.walletAccounts.length?0:Number(c.white)||0;
  c.walletAccounts.push(row('WALLET',{label:'白条账户（补充示例）',kind:'本金',openingBalance:opening,balance:opening,frozen:0,entries:[row('RECHARGE',{type:'充值',amount:500,at:at(12)}),row('DEBIT',{type:'账户消耗',amount:-500,orderId:order.id,at:at(11)})]}));
  c.serviceRecords.push(row('SERVICE',{name:'面部护理',orderId:order.id,assetId:asset.id,qty:2,amount:500,employee:teacher,store,at:at(10)}));
  c.followups.push(row('FOLLOWUP',{name:'护理效果回访',orderId:order.id,status:'已回访',handler:staff,dueAt:at(8),content:'客户反馈良好，已核对剩余 4 次护理权益'}));
  c.performanceEntries.push(row('SALE',{orderId:order.id,metric:'销售业绩',employee:staff,store,amount:1500,unit:'元',commissionAmount:75,paidAmount:0}),row('PERFORMANCE',{orderId:order.id,metric:'服务消耗业绩',employee:teacher,store,amount:500,unit:'元',commissionAmount:50,paidAmount:0}));
  c.snapshotSupplemented=true;return c;
 })};return true;
}
function initializeSnapshotExamples(){let changed=false;for(let r of state.mergeRecords||[])if(mhEnsureSnapshotExamples(r))changed=true;if(changed)persist()}
function mhSnapshotPeople(r){if(mhEnsureSnapshotExamples(r))persist();return r.demo&&r.snapshotExamples?.recordId===r.id?r.snapshotExamples.before:mhData(r).before}
