function mcActiveApplication(g){let key=mrPairKey(mcMembers(g));return state.mergeApplications.find(a=>['待审核','已通过','执行失败'].includes(a.status)&&!a.supersededBy&&(a.candidateId===g.id||mrPairKey(a.pair)===key))}
function mcStatus(g){let members=mcMembers(g);if(g.excluded||mrAllExcluded(members))return '已排除';if(members.length<=1)return '已合并';let a=mcActiveApplication(g);if(a)return a.status==='已通过'?'待执行':a.status==='执行失败'?'待重新申请':'待审核';return g.hits.length?'前置拦截':'待确认'}
