function mcOpen(id){let g=state.mergeCandidates.find(x=>x.id===id);if(!g)return;mrFocus=document.activeElement;mrTask={kind:'candidate',id,tab:'overview',plan:mrPlan(g.detectedMembers,g.rule),dirty:false};render();$('#mergeRecordPanel .icon-btn')?.focus()}
