function mgOpen(key,handle=false){let t=mgTasks().find(t=>t.key===key);if(!t)return;if(t.app?.review){apOpen('merge',t.app.id);return}if(t.app){mrOpen('application',t.app.id);if(handle){mrTask.tab=t.app.status==='已通过'?'confirm':t.app.status==='执行失败'?'overview':'compare';render()}return}if(t.g){if(handle&&!['已排除','已结束','已合并'].includes(t.status)){mrNew(undefined,t.g.id);mrTask.tab='compare';render()}else mcOpen(t.g.id);return}mrOpen('application',t.latest.id)}
function mgShowRecord(key){let t=mgTasks().find(t=>t.key===key),r=t?.records[0];if(r)mrOpen('record',r.id)}
