function mgDetection(r){let g=state.mergeCandidates.find(g=>g.id===r.candidateId);if(!g)return contentModule('检测依据',body('<p class="small muted">本次由人工选择档案并发起申请。</p>'));return contentModule('系统检测依据',body(kv({'检测编号':g.id,'检测来源':g.source,'检测时间':g.time,'触发场景':g.trigger,'匹配依据':esc(g.basis),'原检测档案':g.detectedMembers.length+' 份','当前独立档案':mcMembers(g).length+' 份','检测规则':esc(g.rule.name)+' V'+g.rule.version})))+mcRuleHits(g)}
