function flowReview(){let c=cxEnsure(current());return contentModule('核对纠错范围',body(sourceInfo(c)+'<hr class="light-divider"><p>'+esc(c.description)+'</p><p class="small muted" style="margin-top:12px">期望处理：'+esc(c.expected||'按数据真实归属分离')+'</p>'+btn('查看快照与当前档案','flowCompare()','text')+btn('查看核查材料','evidenceModal()','text')))+contentModule('影响预估',body(impact(c)))}
function cxDirectRows(c=current()){cxEnsure(c);return c.directRows.filter(x=>(!cxDirectType||x.kind===cxDirectType)&&(!cxDirectApplied||[x.id,x.label,x.kind].join(' ').toLowerCase().includes(cxDirectApplied.toLowerCase())))}
function transferTab(){let c=cxEnsure(current()),rows=cxDirectRows(c);return queryModule(`<input aria-label="搜索业务记录" placeholder="记录编号、摘要" value="${esc(cxDirectQuery)}" oninput="cxDirectQuery=this.value">${select([['','全部业务类型'],...[...new Set(c.directRows.map(x=>x.kind))]],cxDirectType,'aria-label="业务类型" onchange="cxDirectType=this.value"')}`,'cxDirectApplied=cxDirectQuery;render()',"cxDirectQuery='';cxDirectApplied='';cxDirectType='';render()")+`<div class="data-toolbar"><span class="small muted">保留原始业务编号，关联记录一并处理。</span>${btn('采用全部建议','confirmAllTransfers()')}</div>`+table(['序号','业务类型 / 编号','内容 / 处理说明','归属','操作'],rows.map(x=>{let i=c.directRows.indexOf(x);return [String(i+1).padStart(2,'0'),esc(x.kind)+'<div class="mono">'+esc(x.id)+'</div>',esc(x.label)+'<div class="tiny muted">'+esc(x.reason)+'</div>',select([['new','迁至 '+c.subname],['main','保留在 '+c.name]],x.to,`aria-label="${esc(x.id)}归属" ${x.executed?'disabled':''} onchange="cxSetDirect(${i},this.value)"`),btn('详情',`cxDirectDetail(${i})`,'text')]}))+(!rows.length?empty('暂无符合条件的业务记录'):'')+cxRestoreUI(c)}
