function cxDirectDetail(i){let c=current(),x=c.directRows[i];modal('业务记录 · '+x.id,kv({'类型':x.kind,'摘要':esc(x.label),'原档案':c.sub,'目标归属':x.to==='new'?clTarget(c):c.cus,'处理细则':x.key==='orders'?'原订单编号与终态保留；支付保留原流水并通过冲销关联；消耗、签到、照片随订单处理':x.key==='tags'?'新档案补录去重标签，主档案同名标签保留':x.key==='wechat'?'保留添加时间和关联客服，重算首次 / 二次加微':x.key==='tickets'?'工单及处理、沟通记录整体迁移':'保留时间、操作人及原关联关系'})+'<hr class="light-divider"><pre class="rule-diff">'+esc(JSON.stringify(x.record,null,2))+'</pre>','',true)}
function cxRestoreUI(c){return contentModule('流退订单的业务补录',c.restoreOrders.length?table(['原订单 / 状态','补录项目','排客时间','处理方式'],c.restoreOrders.map((o,i)=>[esc(o.originalId)+'<div class="tiny muted">原终态不回退</div>',`<input aria-label="${esc(o.originalId)}补录项目" value="${esc(o.project)}" ${c.step>=8?'disabled':''} onchange="cxRestoreField(${i},'project',this.value)">`,`<input aria-label="${esc(o.originalId)}补录排客时间" value="${esc(o.scheduledAt)}" ${c.step>=8?'disabled':''} onchange="cxRestoreField(${i},'scheduledAt',this.value)">`,select([['no','仅保留原流退订单'],['yes','新建纠错补录订单']],o.enabled?'yes':'no',`aria-label="${esc(o.originalId)}补录方式" ${c.step>=8?'disabled':''} onchange="cxRestoreField(${i},'enabled',this.value==='yes')"`)])):body('<p class="small muted">本次没有因合并流退、可补录的订单。</p>'))}
