function manualTab(){let c=cxEnsure(current());return c.manual.map((m,i)=>`<div class="cw-task"><div class="spread"><h3>${esc(m.kind)} · ${esc(m.id)}</h3>${badge(m.to==='unknown'?'待定':m.to?'已指定':'待指定',m.to==='unknown'?'orange':'')}</div><p class="task-meta">${esc(m.label)} · ${esc(m.record.at||m.record.paidAt||'')}<br>${esc(m.record.store||c.store)} · ${esc(m.record.consultant||m.record.by||'')}</p>${btn('查看记录详情',`manualDetail(${i})`,'text')}<div class="cx-choice-line">${select([['','请选择归属'],['main','保留在 '+c.name],['new','迁至 '+c.subname],['unknown','待定 · 明确后再提交']],m.to,`aria-label="${esc(m.id)}归属" ${m.executed?'disabled':''} onchange="setManual(${i},this.value)"`)}</div>${field('判断依据（选填）',`<textarea aria-label="${esc(m.id)}判断依据" ${m.executed?'disabled':''} oninput="flowManualReason(${i},this.value)">${esc(m.reason)}</textarea>`)}</div>`).join('')||body(empty('无合并后新增或变更的数据'))}
function manualDetail(i){let m=current().manual[i];modal('记录详情 · '+m.id,kv({'记录类型':m.kind,'摘要':esc(m.label),'时间':m.record.at||m.record.paidAt||'—','关联订单':m.record.orderId||m.id,'归属依据':esc(m.reason||'尚未填写，提交方案前明确归属')})+'<hr class="light-divider"><pre class="rule-diff">'+esc(JSON.stringify(m.record,null,2))+'</pre>','',true)}
function setManual(i,to){let c=current();if(flowStage(c)!==2||c.manual[i].executed)return;c.manual[i].to=to;c.manual[i].confirmed=to!=='unknown';cxSyncFinance(c);persist();render()}
function flowManualReason(i,v){if(flowStage()!==2)return;current().manual[i].reason=v;persist()}
function cxSyncFinance(c){for(let [i,m] of c.manual.entries()){let type=m.key==='orders'?'新增订单支付':m.key==='vouchers'?'优惠券抵扣':'',amount=m.key==='orders'?Number(m.record.deposit)||0:Number(m.record.amount)||0,key='manual-'+m.id,f=c.finance.find(x=>x.source===key);if(m.to==='new'&&type&&amount&&!f)c.finance.push({id:'FIN-'+key,originalId:'PAY-'+m.id,source:key,type,amount,original:amount,orderId:m.id,reason:'随人工判断的业务归属纠正',confirmed:false,generated:false,enabled:true});else if(m.to!=='new'&&f&&!f.generated)c.finance=c.finance.filter(x=>x!==f)}for(let o of c.restoreOrders){let key='restore-'+o.originalId,f=c.finance.find(x=>x.source===key),covered=c.finance.some(x=>x.source!==key&&x.orderId===o.originalId&&x.type==='预约金收取'&&x.enabled!==false);if(o.enabled&&o.deposit&&!covered&&!f)c.finance.push({id:'FIN-'+key,originalId:'PAY-'+o.originalId,source:key,orderId:o.originalId,type:'预约金收取',amount:o.deposit,original:o.deposit,reason:'纠错补录订单关联预约金',confirmed:false,generated:false,enabled:true});else if((!o.enabled||covered)&&f&&!f.generated)c.finance=c.finance.filter(x=>x!==f)}}
