function flowIdentity(){let c=cxEnsure(current());return contentModule('独立档案基本资料',body('<div class="form-grid cx-profile-form">'+[['name','姓名'],['gender','性别'],['birthday','生日'],['remark','备注']].map(([k,t])=>field(t,`<input aria-label="纠错档案${t}" value="${esc(c.profileDraft[k])}" ${c.identityDone?'disabled':''} oninput="current().profileDraft.${k}=this.value;persist()">`)).join('')+'</div><p class="cw-inline-note">'+(c.newId||'待创建分离档案 · 方案审核通过后创建')+' · 纠错产生 · 关联原档案 '+c.sub+'</p>'))+contentModule('识别维度拆回',table(['识别信息','当前值','处理归属'],c.identityRows.map((x,i)=>[x.type,esc(x.value),select([['move','拆回 '+c.subname],['keep','留在 '+c.name]],x.move?'move':'keep',`aria-label="${x.type}归属" ${c.identityDone?'disabled':''} onchange="flowSetIdentity(${i},this.value)"`)]))+body('<p class="small '+(cxIdentityRemaining(c).length?'positive':'negative')+'">'+(cxIdentityRemaining(c).length?'主档案拆回后仍保留 '+cxIdentityRemaining(c).length+' 个有效识别值。':'本方案会移走主档案全部识别值，请至少选择一项留在主档案后再提交。')+'</p>'))}
