function flowDemoPlan(source=current()){
 let c=clone(cxEnsure(source));c.demoDefaultsUsed=[];
 c.transfer.forEach((t,i)=>{t.to||='new';if(t.to==='split'&&!t.calls)t.calls=['new','new','new'];t.reviewed=true});
 c.directRows.forEach(x=>{x.to||='new';x.reviewed=true});
 c.manual.forEach(m=>{if(!['main','new','unknown'].includes(m.to)){m.to='main';c.demoDefaultsUsed.push(m.id)}m.reason=m.reason?.trim()||'示例方案：按当前客户归属演示';m.confirmed=m.to!=='unknown'});
 cxSyncFinance(c);c.finance.forEach(f=>{if(!Number.isFinite(f.amount)||f.amount<0)f.amount=Math.abs(f.original||0);if(f.amount!==f.original&&!f.reason)f.reason='原型示例调整';f.confirmed=true});
 c.identity=c.identityRows.map(x=>x.move);if(!cxIdentityRemaining(c).length&&c.identityRows.length){c.identityRows[0].move=false;c.identity[0]=false;c.identityRetention='自动保留 '+c.identityRows[0].type+'，避免主档案缺少有效识别信息'}c.planIdentityReviewed=true;return c;
}
