function pcPersonLink(c){return `<button class="inline-link" onclick="pcOpenCustomer(${esc(mrQuote(c.id))})">${esc(c.name)}</button>`}
function pcCustomers(){let map=new Map();for(let r of state.mergeRecords.slice().sort((a,b)=>a.time.localeCompare(b.time))){for(let c of r.snapshot.before){if(!map.has(c.id))map.set(c.id,clone(c))}if(r.revoked){for(let c of r.snapshot.before)map.set(c.id,clone(c))}else{map.set(r.plan.mainId,clone(r.snapshot.after));for(let c of r.pair.filter(c=>c.id!==r.plan.mainId))map.set(c.id,{...clone(c),status:'已合并-从属',mergedInto:r.plan.mainId,lastMerge:r.id})}}
 for(let c of state.mergeCustomers)map.set(c.id,clone(c));for(let c of state.cases){if(c.newId&&!map.has(c.newId))map.set(c.newId,c.resultData?.fresh?clone(c.resultData.fresh):{id:c.newId,name:c.profileDraft?.name||c.subname,phone:'',store:c.store,consultant:'',orders:[],wechat:[],tags:[],white:0,status:'纠错产生',merge:c.merge,correctionCaseId:c.id,originalChildId:c.sub})}return [...map.values()]}
function pcCustomerStatus(c){if(c.status==='已合并-从属')return c.status;if(c.status==='纠错产生'||c.correctionCaseId)return '纠错产生';return state.mergeRecords.some(r=>!r.revoked&&r.plan.mainId===c.id&&mrTime(r.coolingUntil)>Date.now())?'冷静期中':'正常'}
