function pcOpenCustomer(id,tab='overview'){let c=pcCustomers().find(c=>c.id===id);if(!c)return toast('未找到该客户档案');if(mrTask&&mrTask.kind!=='customer'||cxWorkbenchId||cxApplicationOpen||document.querySelector('#modal>[data-overlay-layer]:not(.is-closing)')){pcModalCustomer={id,tab};pcCustomerModal();return}pcModalCustomer=null;if(!mrTask)mrFocus=document.activeElement;mrTask={kind:'customer',id,tab,dirty:false};render();$('#mergeRecordPanel .icon-btn')?.focus()}
