function clBlankForm(){return {reason:'',description:'',expect:'',evidence:[],sourceId:''}}
function clSync(){if(clPlan){clPlan.reason=newForm.reason;clPlan.description=newForm.description;clPlan.expected=newForm.expect;clPlan.evidence=clone(newForm.evidence||[])}return clPlan}
function clTouch(){clSync();clErrors=[];let status=document.querySelector('#correctionApplicationPanel .cl-draft-label');if(status)status.textContent=clDraftStatus()}
function clFingerprint(){clSync();return JSON.stringify({form:newForm,plan:clPlan})}
function clHasContent(){return !!(newForm.sourceId||newForm.reason||newForm.description?.trim()||newForm.expect?.trim()||newForm.evidence?.length)}
function clTarget(c=current()){return c.newId||'待创建分离档案'}
function clMakePlan(source){let c=clone(source);Object.assign(c,{id:'DRAFT-CORRECTION',status:'草稿',step:5,newId:'',approval:0,planReady:false,identityDone:false,planIdentityReviewed:false,resultChecks:[false,false,false],financeApproved:false,logs:[],correctionVersion:0,profileDraft:undefined,createdProfile:undefined,resultData:undefined,executedAt:undefined,financialTriples:undefined,transfer:Array.from({length:8},()=>({to:'',reviewed:false,executed:false})),manual:[],identity:undefined});c.correctionData=clone(qaSourceData(source));c.finance=clone(source.finance||[]).map(f=>({...f,amount:Number(f.original??f.amount)||0,original:Number(f.original??f.amount)||0,enabled:true,generated:false,confirmed:false,reason:'',generatedAt:undefined}));cxEnsure(c);bpEnsure(c);c.businessPlan.performanceLinkVersion=1;return ctInitialize(c)}
function clSource(id){return cxSources().find(c=>c.id===id)}
function clSelectSource(id){let source=clSource(id);if(!source)return;let existing=ctActiveCase(source);if(existing){cxApplicationOpen=false;clPlan=null;closeModal();flowOpen(existing.id);return}let record=state.mergeRecords.find(r=>r.id===source.merge);if(record?.revoked){toast('该次合并已撤销，不能发起纠错');return}if(record&&mrTime(record.coolingUntil)>Date.now()){closeModal();cxApplicationOpen=false;clPlan=null;mrOpen('record',record.id);return}if(record&&(record.archived||mrTime(record.retainUntil)<Date.now())){closeModal();mrArchived(record.id);return}newForm.sourceId=id;clPlan=clMakePlan(source);clStep=1;clTouch();closeModal();render()}
function clCreateDraftSnapshot(){clSync();return {id:clDraftId||clNextId('CD',state.correctionDrafts||[]),schema:5,form:clone(newForm),plan:clPlan?clone(clPlan):null,stage:clStep,tab:flowTab,savedAt:now(),author:'张三'}}
function clSaveDraft(close=false){if(!clHasContent()){clErrors=[{step:1,message:'请先选择合并记录或填写申请内容，再保存草稿。'}];render();return false}let draft=clCreateDraftSnapshot();clDraftId=draft.id;state.correctionDrafts||=[];let i=state.correctionDrafts.findIndex(d=>d.id===draft.id);if(i<0)state.correctionDrafts.unshift(draft);else state.correctionDrafts[i]=draft;persist();clSavedFingerprint=clFingerprint();clErrors=[];if(close)clCloseNow();else render();toast('草稿已保存，尚未生成正式工单');return true}
function clEditDraft(id){let d=state.correctionDrafts?.find(d=>d.id===id);if(!d)return;newForm=clone(d.form);clPlan=d.plan?clone(d.plan):null;if(clPlan&&clPlan.businessVersion!==5){clPlan.legacyBusinessDraft=clone(d.plan);bpEnsure(clPlan)}let needsTarget=clPlan&&!clPlan.businessPlan?.targetDefinitionVersion;if(needsTarget)ctUpgradeDraft(clPlan);clDraftId=id;let oldStage=d.stage||1;clStep=needsTarget?1:d.schema>=5?oldStage:oldStage===1?1:oldStage+1;if(clPlan){ctFormUpgrade(clPlan);clPlan.businessPlan.performanceLinkVersion=1}flowTab=d.tab||'manual';clErrors=[];clSavedFingerprint=clFingerprint();cxOpenApplication(true)}
function clCloseNow(){cxApplicationOpen=false;clPlan=null;clDraftId=null;clErrors=[];render();setTimeout(()=>{let el=cxApplicationFocus;if(!el?.isConnected)el=[...document.querySelectorAll('#main button')].find(b=>b.textContent.trim()==='发起纠错')||document.querySelector('#nav .active');el?.focus({preventScroll:true})},drawerMotionTime()+16)}
function clClose(){if(clHasContent()&&clFingerprint()!==clSavedFingerprint){modal('保存未提交的纠错方案？','<p>当前内容尚未保存为草稿。保存草稿不会生成正式工单或客户档案。</p>',btn('继续编辑','closeModal()')+btn('放弃未保存修改','closeModal();clCloseNow()')+btn('保存草稿并关闭','if(clSaveDraft(true))closeModal()','primary'));return}clCloseNow()}
function clNext(){clSync();if(clStep===1){clErrors=clValidate(false,1);if(clErrors.length){render();return}clStep=2}else if(clStep===2){clErrors=clValidate(false,2);if(clErrors.length){render();return}clStep=3;flowTab=bpBusiness(clPlan)?'orders':clPlan.businessPlan.scope==='performance'?'staff':'identity'}else if(clStep===3){clErrors=clValidate(true);if(clErrors.length){render();return}clStep=4}render();document.querySelector('#correctionApplicationPanel .merge-drawer-body')?.scrollTo(0,0)}
function clBack(){clStep=Math.max(1,clStep-1);clErrors=[];render()}
function clValidate(full=true,stage=4){clSync();let out=[],add=(message,step=1,tab='')=>out.push({message,step,tab});if(!newForm.reason)add('请选择纠错原因。');if(!newForm.description?.trim())add('请填写问题说明，说明误合并情况与纠错依据。');if(!newForm.sourceId||!clPlan)add('请选择本次需要纠错的合并记录。');if(!clPlan||stage===1)return out;if(clPlan.businessVersion===5){out.push(...ctTargetErrors(clPlan));if(full)out.push(...bpValidate(clPlan));return out.filter((x,i,a)=>a.findIndex(y=>y.message===x.message)===i)}return out}
function clErrorUI(){return clErrors.length?`<div class="cl-validation" role="alert"><strong>请完善以下内容</strong>${clErrors.map((x,i)=>`<button class="inline-link" onclick="clLocateError(${i})">${esc(x.message)}</button>`).join('')}</div>`:''}
function clLocateError(i){let e=clErrors[i];if(!e)return;clStep=e.step;if(e.tab)flowTab=e.tab;render();document.querySelector('#correctionApplicationPanel .merge-drawer-body')?.scrollTo(0,0)}
function clPlanEditor(){let c=clPlan;if(c?.businessVersion===5)return bpEditor();return `<div class="tabs cw-plan-tabs" role="tablist" aria-label="纠错方案分类">${[['manual','新增数据归属'],['transfer','业务记录'],['finance','资金处理'],['identity','档案与身份']].map(([k,t])=>`<button class="tab ${flowTab===k?'active':''}" role="tab" aria-selected="${flowTab===k}" tabindex="${flowTab===k?0:-1}" onkeydown="cxPlanTabKey(event)" onclick="flowTab='${k}';render()">${t}</button>`).join('')}</div><div role="tabpanel">${flowTab==='manual'?manualTab():flowTab==='transfer'?transferTab():flowTab==='finance'?financeTab():flowIdentity()}</div>`}
function clSummary(c){if(c.businessVersion===5)return bpSummary(c);return contentModule('申请与处理范围',body(kv({'纠错原因':esc(c.reason),'问题说明':esc(c.description),'期望处理':esc(c.expected||'未补充'),'原合并记录':esc(c.merge),'当前主档案':esc(c.name)+' · '+esc(c.cus),'分离原档案':esc(c.subname)+' · '+esc(c.sub),'分离档案资料':esc(c.profileDraft.name)+' · '+(c.newId?esc(c.newId):'审核通过后创建'),'档案性别':esc(c.profileDraft.gender||'未填写'),'档案生日':esc(c.profileDraft.birthday||'未填写'),'档案备注':esc(c.profileDraft.remark||'未填写'),'核查材料':(c.evidence||[]).map(esc).join('、')||'未上传'})))+contentModule('业务归属方案',table(['记录 / 类型','处理动作','处理依据'],c.directRows.map(x=>[esc(x.id)+' · '+esc(x.kind),x.to==='new'?(c.newId?'迁至分离档案':'迁至待创建档案'):'保留主档案',esc(x.reason)]).concat(c.manual.map(x=>[esc(x.id)+' · '+esc(x.kind),x.to==='new'?(c.newId?'迁至分离档案':'迁至待创建档案'):x.to==='main'?'保留主档案':'尚未确定',esc(x.reason||'按本次明确选择处理')]))))+contentModule('拟定资金处理',table(['原流水 / 类型','原始金额','处理动作','主档案变动','分离档案变动','依据'],c.finance.map(f=>[esc(f.originalId||f.id)+' · '+esc(f.type),cxSign(cxSigned(f,true)),f.enabled===false?'保留原流水':'冲销并补录',cxSign(-cxSigned(f)),cxSign(cxSigned(f)),esc(f.reason||'沿用原始金额')])) )+contentModule('身份信息方案',table(['识别信息','识别值','处理动作'],c.identityRows.map(x=>[x.type,esc(x.value),x.move?(c.newId?'拆回分离档案':'拆回待创建档案'):'保留主档案'])))+contentModule('订单补录方案',table(['原订单','拟补录项目','排客时间','预约金'],c.restoreOrders.filter(x=>x.enabled).map(x=>[esc(x.originalId),esc(x.project),esc(x.scheduledAt||'待排客'),money(x.deposit||0)])))}
function clComposerAside(){let c=clSync();if(c?.businessVersion===5)return bpAside(c);return contentModule('方案摘要',body(c?kv({'正式工单':'尚未提交','分离档案':'审核通过后创建','业务记录':c.directRows.length+' 条','待明确归属':c.manual.filter(x=>!['main','new'].includes(x.to)).length+' 条','资金处理':money(flowTotal(c)),'身份拆回':c.identityRows.filter(x=>x.move).length+' 项'}):'<p class="small muted">选择合并记录后，准备业务、资金及身份处理方案。</p>'))+contentModule('提交后处理',body('<ol class="cx-flow-note"><li>完整方案提交审核</li><li>原型模拟审核通过</li><li>创建新档案并由系统执行纠正</li><li>在工单详情查看结果及调整单</li></ol>'))}
function clComposerDrawer(){
 let c=clSync(),titles=['申请信息',c&&!bpBusiness(c)?'客户档案':'新档案信息','纠错方案','提交确认'];
 let content=clStep===1?clApplicationUI(c):!c?body(empty('请先选择合并记录')):clStep===2?ctTargetUI(c):clStep===3?clPlanEditor():c.businessVersion===5?clReviewUI(c):clSummary(c);
 let previous=clStep===3&&c?.businessVersion===5?btn('上一项','bpPrevSection()'):clStep>1?btn('上一步','clBack()'):'';
 let next=clStep===3&&c?.businessVersion===5?btn(bpNextLabel(),'bpNextSection()','primary'):clStep<4?btn('下一步','clNext()','primary'):btn('提交审核','submitApplication(false)','primary');
 return `<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector('#modal>[data-overlay-layer]'))cxCloseApplication()"><section class="merge-drawer" id="correctionApplicationPanel" role="dialog" aria-modal="true" aria-label="发起纠错"><header class="merge-drawer-head"><div class="cx-workbench-heading"><h2>发起纠错</h2><span class="cl-draft-label">${clDraftStatus()}</span></div><button class="icon-btn" aria-label="关闭纠错方案" onclick="cxCloseApplication()">${icon('close')}</button></header><div class="cl-steps" role="tablist" aria-label="纠错申请步骤">${titles.map((t,i)=>`<button id="cl-step-${i+1}" class="${clStep===i+1?'active':clStep>i+1?'done':''}" role="tab" aria-controls="cl-active-step" aria-selected="${clStep===i+1}" tabindex="${clStep===i+1?0:-1}" onclick="clGoStep(${i+1})" onkeydown="clStepKey(event,${i+1})"><span>${i+1}</span>${t}</button>`).join('')}</div><div class="merge-drawer-body" data-drawer-scroll="correction-application">${clErrorUI()}<div id="cl-active-step" role="tabpanel" aria-labelledby="cl-step-${clStep}" class="cl-form-content cl-form-step-${clStep}">${content}</div></div><footer class="merge-drawer-foot"><div class="actions">${btn('取消','cxCloseApplication()')}${btn('保存草稿','clSaveDraft()')}</div><div class="actions">${previous}${next}</div></footer></section></div>`;
}
function clApplicationUI(c){
 let record=c?`<div class="cl-record-control"><div><strong class="cl-record-name">${esc(ctMergeTitle(c))}</strong><div class="small muted">${esc(c.mergeDate||state.mergeRecords.find(r=>r.id===c.merge)?.time||'—')} · 记录 ID ${uiId(c.merge)}</div><div class="small">当前档案：${esc(c.name)} · ${esc(uiPhone(c.correctionData?.current?.phone||c.phone))} · ID ${uiId(c.cus)}</div></div>${btn('更换记录','flowPickSource()','text')}</div>`:btn('选择合并记录','flowPickSource()');
 let related=field('合并记录',record,true)+(c?.businessVersion===5?bpSourceLocationUI(c):'');
 let reasons='<div class="cl-form-columns">'+field('纠错原因',select([['','请选择纠错原因'],'合并了不同人','主子判定错误','订单仲裁错误','数据迁移错误','其他'],newForm.reason,'aria-label="纠错原因" onchange="newForm.reason=this.value;flowDraftSave()"'),true)+(c?.businessVersion===5?ctScopeUI(c):'')+'</div>';
 reasons+=field('问题说明','<textarea id="newDescription" rows="3" aria-label="问题说明" placeholder="说明哪里合并有误，以及核实依据" oninput="newForm.description=this.value;flowDraftSave()">'+esc(newForm.description)+'</textarea>',true)+field('核查证据',clUploadUI());
 let extra=field('期望处理','<textarea rows="2" aria-label="期望处理" placeholder="补充本次希望调整的内容（选填）" oninput="newForm.expect=this.value;flowDraftSave()">'+esc(newForm.expect)+'</textarea>');
 return '<div class="cl-standard-form"><section class="cl-form-section"><div class="cl-section-head"><h3>关联合并记录</h3></div>'+related+'</section><section class="cl-form-section"><div class="cl-section-head"><h3>申请原因与依据</h3></div>'+reasons+extra+'</section></div>';
}
function clUploadUI(){return '<div class="cl-upload-control"><div class="actions"><label class="btn cl-upload-button">'+icon('upload')+'<span>上传附件</span><input type="file" aria-label="上传证据材料" multiple hidden style="display:none" onchange="addFiles(this.files)"></label>'+btn('示例材料','sampleFiles()','text')+'<span class="small muted">图片、录音或文档</span></div><div class="files">'+newForm.evidence.map((f,i)=>'<div class="file-row">'+icon('file')+'<span class="flex1">'+esc(f)+'</span>'+btn('移除','newForm.evidence.splice('+i+',1);flowDraftSave();render()','text')+'</div>').join('')+'</div></div>'}
function clDraftRows(){let f=filter;return (state.correctionDrafts||[]).filter(d=>{let c=d.plan||{},text=[d.id,d.legacyCaseId,d.form?.description,c.name,c.subname,c.profileDraft?.name,c.businessPlan?.targetSnapshot?.name,c.merge,c.phone].join(' ').toLowerCase();return (!f.q||text.includes(uiQuery(f.q).toLowerCase()))&&(!f.store||c.store===f.store)&&(!f.from||d.savedAt.slice(0,10)>=f.from)&&(!f.to||d.savedAt.slice(0,10)<=f.to)&&(!f.author||d.author===f.author)&&(!f.risk||(f.risk==='高风险')===!!c.high)}).sort((a,b)=>b.savedAt.localeCompare(a.savedAt))}
function clDraftList(){let all=clDraftRows(),pages=Math.max(1,Math.ceil(all.length/7));pageNo=Math.max(1,Math.min(pageNo,pages));return table(['草稿','涉及客户 / 合并记录','申请说明','保存时间','状态','操作'],all.slice((pageNo-1)*7,pageNo*7).map(d=>[esc(d.id)+(d.legacyCaseId?'<div class="tiny muted">旧版 '+esc(d.legacyCaseId)+' 转为草稿</div>':''),esc(d.plan?d.plan.businessVersion===5?d.plan.name+' / '+(bpBusiness(d.plan)?ctTargetLabel(d.plan):'仅纠正当前档案'):[d.plan.name,d.plan.subname].join(' / '):'尚未选择')+'<div class="tiny muted">'+esc(d.plan?.merge||'—')+'</div>',esc(d.form.description||'待补充问题说明'),esc(d.savedAt),badge('草稿 · 未提交'),btn('继续编辑',`clEditDraft(${mrQuote(d.id)})`,'text')]))+(!all.length?empty('暂无纠错草稿','填写方案后可保存草稿。'):'')+`<div class="pagination"><span>共 ${all.length} 份草稿</span><div>${btn('上一页','pageNo=Math.max(1,pageNo-1);render()')}${pageNo} / ${pages}${btn('下一页',`pageNo=Math.min(${pages},pageNo+1);render()`)}</div></div>`}
function clNextId(prefix,pool){let stamp=now().slice(0,10).replaceAll('-',''),n=1;while(pool.some(x=>x.id===prefix+'-'+stamp+'-'+String(n).padStart(3,'0')))n++;return prefix+'-'+stamp+'-'+String(n).padStart(3,'0')}
function clSubmit(){if(!cxApplicationOpen)return;if(!clPlan){clErrors=[{step:1,message:'请选择合并记录并填写完整方案后提交。'}];render();return}if(clStep!==4){clErrors=[{message:'请完成方案，并在提交确认页核对后提交。',step:Math.min(clStep,3)}];render();return}clErrors=clValidate(true);if(clErrors.length){render();return}let existing=ctActiveCase(clPlan);if(existing){cxApplicationOpen=false;clPlan=null;flowOpen(existing.id);toast('已打开该当前档案的进行中纠错工单');return}let c=clone(clSync());c.id=clNextId('EC',state.cases.concat((state.legacyCorrectionCases||[])));Object.assign(c,{workflowVersion:4,submittedAt:now(),date:now(),author:'张三',status:'待审核',approval:0,newId:'',logs:[],step:5,planReady:true,financeApproved:false,resultChecks:[false,false,false]});delete c.sourceDraftId;c.finance.forEach((f,i)=>{if(!f.originalId||f.originalId.includes('DRAFT-CORRECTION'))f.originalId='SOURCE-'+(i+1);f.id='FIN-'+c.id+'-'+(i+1);f.generated=false});c.amount=c.businessVersion===5?(bpBusiness(c)?bpRound(c.businessPlan.funds.reduce((sum,f)=>sum+Math.abs(bpChosenAmount(f)),0)):0):flowTotal(c);c.submittedPlan=clPlanSnapshot(c);cxEvent(c,1,'提交完整纠错方案审核，包含申请依据、业务归属、资金和身份方案','草稿','待审核');state.cases.unshift(c);let draftId=clDraftId;state.correctionDrafts=(state.correctionDrafts||[]).filter(d=>d.id!==draftId);delete state.applicationDraft;let source=state.mergeSources.find(s=>s.merge===c.merge&&s.sub===c.sub);if(source)source.correctionCaseId=c.id;let record=state.mergeRecords.find(r=>r.id===c.merge);if(record){record.correctionId=c.id;mrEvent(record,'提交完整纠错工单 '+c.id)}activeId=c.id;cxApplicationOpen=false;clPlan=null;clDraftId=null;clErrors=[];newForm=clBlankForm();apSeal(c,'correction');persist();apOpen('correction',c.id);toast('完整纠错方案已提交审核；全部节点通过后才建档并执行')}
function clPlanSnapshot(c){let result={};for(let k of ['merge','mergeDate','cus','sub','name','subname','phone','store','reason','description','expected','evidence','correctionData','profileDraft','directRows','manual','finance','identityRows','identity','restoreOrders','transfer','cross','businessVersion','businessPlan','legacyBusinessDraft','priorCaseId','businessSourceId'])result[k]=clone(c[k]??null);return result}
function clApprove(c){if(c.review&&c.review.status!=='approved')return;if(c.workflowVersion!==4||c.approval)return;if(c.businessVersion===5){bpApprove(c);return}c.approvedAt=now();c.approval=1;c.approvalResult=c.review?'已审核通过':'已通过（原型模拟）';c.approvedPlan=clone(c.submittedPlan);cxEvent(c,2,c.review?'完整方案审核通过，固定执行方案':'完整方案审核通过（原型模拟），固定执行方案','待审核','已通过');c.newId=clNextId('ECF',pcCustomers());c.profileCreatedAt=now();c.createdProfile={...clone(c.profileDraft),id:c.newId,status:'纠错产生',merge:c.merge,correctionCaseId:c.id,originalChildId:c.sub,store:c.store,phone:'',orders:[],payments:[],white:0,wechat:[],tags:[],calls:[],images:[],tickets:[],projects:[],checkins:[],businessReady:false};state.mergeCustomers.push(clone(c.createdProfile));cxEvent(c,3,'审核通过后创建空的分离档案','未创建',c.newId);c.status='待执行';c.execution={attempts:0,status:'待执行'};c.step=5;c.planReady=true}
function clSchedule(id){if(clJobs.has(id))return;let timer=setTimeout(()=>{clJobs.delete(id);clExecute(id)},400);clJobs.set(id,timer)}
