function bpStaffRoute(c,r){
 let p=c.businessPlan,e=r.record,order=p.orders.find(o=>o.id===e.orderId),fundId=e.fundId||e.paymentId||e.transactionId||e.rechargeId||e.sourceBusinessId||(!e.orderId&&e.acceptanceExample&&/-PERFORMANCE-7$/.test(e.id)?e.id.replace(/-PERFORMANCE-7$/,'-WALLET-1'):''),fund=!e.orderId&&p.performanceLinkVersion===1&&fundId?p.funds.find(f=>f.id===fundId||f.record.originalId===fundId):null;
 let ratio=!bpBusiness(c)?0:order?(order.to==='target'?1:0):fund&&Math.abs(fund.signed)>.001?Math.min(1,Math.abs(bpChosenAmount(fund)/fund.signed)):0;
 return {kind:order?'order':fund?'fund':'unlinked',order,fund,ratio,reference:order?.id||fund?.id||e.orderId||fundId||'',pending:bpBusiness(c)&&(order?!['main','target'].includes(order.to):fund?!['main','target','split'].includes(fund.to):false)};
}
function bpStaffMoved(c,r){let route=bpStaffRoute(c,r),amount=bpRound(bpNum(r.amount)*route.ratio),commission=bpRound(r.beneficiaries.reduce((sum,b)=>sum+bpRound(bpNum(b.commission)*route.ratio),0));return {...route,amount,commission}}
function bpStaffOrderCell(c,r){
 let link=bpStaffRoute(c,r),noun=link.kind==='fund'?'资金':'订单',destination=link.pending?'随'+noun+'归属确定':link.ratio===1?'随'+noun+'转入 · '+bpTargetName(c):link.ratio>0?'随资金拆分 · '+bpRound(link.ratio*100)+'%转入 '+bpTargetName(c):'保留 · '+c.name;
 let name=link.order?.record.name||link.fund?.record.type||(r.record.orderId?'关联订单不在本次范围':'未关联订单或资金');return esc(name)+'<div class="tiny muted">'+esc(link.reference)+'</div><div class="tiny muted">'+esc(r.record.metric)+' · '+esc(r.record.period||'未记录月份')+'</div><div class="tiny muted">'+esc(destination)+'</div>';
}
