 return contentModule('业绩随业务迁移',table(['关联业务 / 业绩类型','迁移去向','迁移业绩 / 提成','员工分配'],rows.map(({r,move})=>[esc(move.reference)+'<div class="tiny muted">'+esc(r.record.metric)+'</div>',esc(c.name)+' → '+esc(bpTargetName(c))+(move.ratio<1?'<div class="tiny muted">随资金迁移 '+bpRound(move.ratio*100)+'%</div>':''),move.amount+' '+esc(r.record.unit||'元')+' / '+money(move.commission),r.beneficiaries.map(b=>esc(b.employee)+' · '+b.share+'%').join('、')+'<div class="tiny muted">'+(bpStaffChanged(r)?'包含本次明确的员工纠正':'沿用原员工分配')+'</div>']))+(rows.length?'':body('<p class="small muted">本次没有需要随订单或资金迁移的业绩。</p>')));
