function bpStaffRecordParts(c,r,record){
 let move=bpStaffMoved(c,r);if(move.ratio<=0)return {main:record,target:null,move};if(move.ratio>=1)return {main:null,target:record,move};
 let target=clone(record),main=clone(record);target.id='PERF-'+c.id+'-'+r.id;target.sourcePerformanceId=record.sourcePerformanceId||r.id;target.fundId='IN-'+c.id+'-'+move.fund.id;target.amount=move.amount;main.amount=bpRound(record.amount-target.amount);
 target.beneficiaries=record.beneficiaries.map(b=>({...clone(b),commission:bpRound(bpNum(b.commission)*move.ratio)}));main.beneficiaries=record.beneficiaries.map((b,i)=>({...clone(b),commission:bpRound(bpNum(b.commission)-target.beneficiaries[i].commission)}));
 for(let part of [main,target])part.commissionAmount=bpRound(part.beneficiaries.reduce((sum,b)=>sum+bpNum(b.commission),0));target.paidAmount=bpRound(bpNum(record.paidAmount)*move.ratio);main.paidAmount=bpRound(bpNum(record.paidAmount)-target.paidAmount);target.historicalPaidAllocation=true;main.historicalPaidAllocation=true;return {main,target,move};
}
