function bpResolveLive(id){let seen=new Set(),live=state.mergeCustomers.find(x=>x.id===id);while(live?.mergedInto&&!seen.has(live.id)){seen.add(live.id);live=state.mergeCustomers.find(x=>x.id===live.mergedInto)}return live&&!live.mergedInto&&!live.inactive?live:null}
