const UI_ID_PATTERN=/\b(?:[A-Z][A-Z0-9]{1,14}|merge|arb|source)-(?:[A-Za-z0-9_]+-)*[A-Za-z0-9_]+\b/g;
let uiIdsReady=false,uiIdsUsed=new Set(),uiIdsChanged=false,uiIdObserver=null;
function uiAssignId(id){let map=state.uiIds.map;if(map[id])return map[id];let preferred=/^CUS-(\d{5})$/.exec(id)?.[1],candidate=preferred&&!uiIdsUsed.has(preferred)?preferred:'';if(!candidate){let next=state.uiIds.next||60000;while(uiIdsUsed.has(String(next))&&next<=99999)next++;if(next>99999){next=10000;while(uiIdsUsed.has(String(next))&&next<=99999)next++}if(next>99999)throw Error('五位 ID 已用完');candidate=String(next);state.uiIds.next=next+1}map[id]=candidate;uiIdsUsed.add(candidate);uiIdsChanged=true;return candidate}
function uiEnsureIds(){if(uiIdsReady)return;state.uiIds||={map:{},next:60000};state.uiIds.map||={};uiIdsUsed=new Set(Object.values(state.uiIds.map));uiIdsReady=true;let ids=[...new Set(JSON.stringify(state).match(UI_ID_PATTERN)||[])];ids.filter(x=>/^CUS-\d{5}$/.test(x)).sort().forEach(uiAssignId);ids.forEach(uiAssignId)}
function uiId(id){if(!id)return '—';if(/^\d{5}$/.test(String(id)))return String(id);uiEnsureIds();return uiAssignId(String(id))}
function uiDisplayText(text){uiEnsureIds();return String(text??'').replace(UI_ID_PATTERN,id=>uiAssignId(id))}
function uiQuery(value){uiEnsureIds();let query=String(value||'').trim();if(/^\d{5}$/.test(query)){let key=Object.keys(state.uiIds.map).find(key=>state.uiIds.map[key]===query);if(key)return key}return query}
function uiPhone(value){let phone=String(value||'').replace(/^\+86[ -]?/,'').replace(/\s/g,'');return /^\d{11}$/.test(phone)?phone.slice(0,3)+'****'+phone.slice(-4):phone||'无手机号'}
function uiNormalizeIds(){if(!document.body||!document.createTreeWalker)return;uiEnsureIds();let walker=document.createTreeWalker(document.body,4),node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,textarea,input,.ub-workspace,.ub-drawer'))continue;let next=uiDisplayText(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next}for(let el of document.querySelectorAll('[aria-label],[title],[placeholder]'))for(let key of ['aria-label','title','placeholder']){if(el.closest('.ub-workspace,.ub-drawer'))continue;let value=el.getAttribute(key);if(value){let next=uiDisplayText(value);if(next!==value)el.setAttribute(key,next)}}if(document.title)document.title=uiDisplayText(document.title);if(uiIdsChanged){uiIdsChanged=false;persist()}}
function uiObserveIds(){if(typeof MutationObserver==='undefined'||!document.body)return;uiIdObserver=new MutationObserver(()=>uiNormalizeIds());uiIdObserver.observe(document.body,{subtree:true,childList:true,characterData:true});uiNormalizeIds()}
