function apTitle(o,kind){return kind==='merge'?o.pair.map(c=>c.name).join(' + '):o.name+' · '+o.reason}
function apListPage(mobile=false){if(mobile)return apMobileList();let rows=apRows(),count=rows.length,pages=Math.max(1,Math.ceil(count/10));apPage=Math.min(pages,apPage);rows=rows.slice((apPage-1)*10,apPage*10);let query='<section class="panel ap-query">'+apTabs([['merge','合并审核'],['correction','纠错审核'],['history','审核记录']],apView,k=>`apSwitch('${k}')`)+apFiltersUI()+'</section>',list=table(['工单 / 客户','来源 / 风险','涉及门店','申请人 / 提交时间','当前节点','操作'],rows.map(({o,kind})=>[esc(apTitle(o,kind))+'<div class="tiny muted">'+(kind==='merge'?'合并':'纠错')+'工单 '+uiId(o.id)+'</div>',esc(o.source||'纠错申请')+'<div class="tiny">'+(o.high?badge('高风险','orange'):esc(o.review?.urgency||'普通'))+'</div><div class="tiny muted">'+esc((o.reasons||[]).join('；'))+'</div>',esc(o.store),esc(o.review?.submittedBy||o.author)+'<div class="tiny muted">'+esc(o.review?.submittedAt||o.time||o.date)+'</div>',apBadge(apStatus(o,kind))+'<div class="tiny muted">'+esc(o.review?.assignee||'历史记录')+'</div>',btn('查看审核',`apOpen('${kind}',${mrQuote(o.id)})`,'text')]));if(!count)list='<div class="ap-empty">暂无符合条件的审核工单</div>';return query+contentModule(apView==='history'?'审核记录':apView==='merge'?'合并审核':'纠错审核',list+'<div class="pagination"><span>共 '+count+' 条</span><div class="actions">'+btn('上一页','apTurn(-1)')+apPage+' / '+pages+btn('下一页','apTurn(1)')+'</div></div>')}
function apTurn(n){apPage=Math.max(1,apPage+n);render()}
function apOpen(kind,id){let o=apItem(kind,id);if(!o)return;if(apIsMobile()&&!apTask)apOpen.listScroll=$('.ap-mobile-scroll')?.scrollTop||0;apTask={kind,id,tab:'summary',mobileTab:'plan',mobileSection:kind==='merge'?'customers':'plan',person:kind==='merge'?o.pair[0]?.id:'',section:'orders',note:'',dirty:false};if(kind==='correction')activeId=id;mrTask=null;cxWorkbenchId=null;cxApplicationOpen=false;apSheet=null;render();if(apIsMobile())$('.ap-mobile-scroll').scrollTop=0}
