function apCommit(action){let o=apObj();if(!o)return;let note=$('#apDecisionNote')?.value.trim()||'',kind=apTask.kind,r=o.review,actor=apReviewer(o);if(action==='confirm'){if(!o.resultData||o.status==='已完成')return;if(!note){apActionError('请填写财务确认意见');return;}o.status='已完成';o.step=9;o.financeApproved=true;o.resultChecks=[true,true,true];o.completedAt=now();o.completedBy=actor;o.financeOpinion=note;o.corrected=!o.businessPlan?.targetDefinitionVersion&&o.businessPlan?.scope==='split';let source=state.mergeSources.find(s=>s.merge===o.merge&&s.sub===o.sub),record=state.mergeRecords.find(r=>r.id===o.merge);if(source&&o.corrected){source.corrected=true;source.correctionCaseId=o.id}if(record)mrEvent(record,'纠错工单 '+o.id+' 的业务与调整单结果已确认');for(let a of state.performanceAdjustments||[])if(a.caseId===o.id)a.status='已确认（待实际计奖系统入账）';if(r)apEvent(o,'财务确认调整单',note,actor);cxEvent(o,9,'财务确认调整单','待确认','已完成');apDismiss();persist();render();return}if(!apCanAct())return;if(['reject','transfer'].includes(action)&&!note){apActionError(action==='reject'?'请填写驳回原因':'请填写转交说明');return}if(action==='reject'){r.status='rejected';o.status='已驳回';o.reviewNote=note;apEvent(o,'驳回',note,actor);apTask.dirty=false}else if(action==='transfer'){let to=$('#apTransferTo')?.value;if(!AP_ACTORS.includes(to)||to===actor)return;apEvent(o,'转交',actor+' → '+to+'；'+note);r.assignee=to}else if(action==='approve'){if(kind==='merge'){if(mrApplicationConflict(o)){toast('档案状态已经变化，请驳回并重新提交方案');return}if(!o.pair.some(c=>c.id===apMergePlan(o).mainId))return;r.approvedPlan=clone(r.submittedPlan||o.plan);o.plan=clone(r.approvedPlan);o.approvedAt=now();o.approvedBy=actor;apEvent(o,'审核通过',apTask.note||'同意申请人提交的合并方案，系统按此方案执行');r.status='approved';o.status='已通过';apTask.dirty=false;apScheduleMerge(o.id)}else if(o.high&&r.status==='pending'){r.status='finance';r.assignee='财务加签人';o.status='待财务加签';apEvent(o,'总部审核通过',apTask.note||'完整方案提交财务核对',actor)}else{if(r.status==='finance'&&!note){apActionError('请填写财务核对结论');return}r.status='approved';r.approvedPlan=clone(o.submittedPlan);r.financeConfirmed=o.high;apEvent(o,o.high?'财务加签通过':'店长审核通过',note||apTask.note||'同意完整纠错方案');clApprove(o);o.approvedBy=actor;clSchedule(o.id)}}apDismiss();persist();render()}
function apScheduleMerge(id){if(apJobs.has(id))return;apJobs.set(id,setTimeout(()=>{apJobs.delete(id);apExecuteMerge(id)},400))}
function apExecuteMerge(id){let a=apItem('merge',id);if(!a||a.review?.status!=='approved'||a.recordId||a.status==='执行中')return false;a.status='执行中';try{if(mrApplicationConflict(a)||Object.entries(a.review.baseline||{}).some(([id,data])=>JSON.stringify(state.mergeCustomers.find(c=>c.id===id)||null)!==data))throw Error('提交后客户档案或订单数据已变化，未迁移数据；需重新核实并提交审批');let plan=clone(a.review.approvedPlan),r=mrBuildRecord(a.pair,plan,a.rule,{method:'人工合并',trigger:a.trigger,match:a.match,applicationId:a.id,author:a.approvedBy||'审核人'}),impact=mrImpact(a.pair,plan);pcStampImpact(impact.after,r.id);r.candidateId=a.candidateId||'';r.approvalSnapshot=clone(a.review);for(let old of state.mergeRecords)if(!old.revoked&&old.pair.some(c=>a.pair.some(x=>x.id===c.id)))old.followUp=true;for(let c of a.pair){let i=state.mergeCustomers.findIndex(x=>x.id===c.id);if(i>=0)state.mergeCustomers[i]=c.id===impact.main.id?{...clone(impact.after),lastMerge:r.id}:{...clone(c),status:'已合并-从属',mergedInto:impact.main.id,lastMerge:r.id}}a.status='已执行';a.recordId=r.id;a.executedAt=r.time;apEvent(a,'系统执行完成','生成合并记录 '+uiId(r.id),'系统');mrEvent(a,'审核通过后系统执行完成，生成记录 '+r.id,'系统');state.mergeRecords.unshift(r);let g=state.mergeCandidates.find(g=>g.id===a.candidateId);if(g)mrEvent(g,'审核通过后执行合并 '+r.id,'系统');persist();render();toast('审核通过，系统合并已完成');return true}catch(e){a.status='执行失败';a.review.executionError=e.message;apEvent(a,'执行失败',e.message,'系统');persist();render();return false}}
function apRetry(){let o=apObj();if(o.review?.status!=='approved'||o.status!=='执行失败')return;if(apTask.kind==='merge')apScheduleMerge(o.id);else clSchedule(o.id);toast('已提交系统重试')}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&window.PCUI?.isPopupOpen())return;if(!apIsMobile()||!apSheet)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();apDismiss()}else if(e.key==='Tab'){let items=[...document.querySelectorAll('#apMobileSheet button,#apMobileSheet textarea,#apMobileSheet select,#apMobileSheet input')].filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}},true);
